      { name: 'Ter', alerts: 300, iocs: 139 },
      { name: 'Qua', alerts: 200, iocs: 980 },
      { name: 'Qui', alerts: 278, iocs: 390 },
      { name: 'Sex', alerts: 189, iocs: 480 },
      { name: 'Sab', alerts: 239, iocs: 380 },
      { name: 'Dom', alerts: 349, iocs: 430 },
    ];

    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-bold text-white mb-1">Visão Geral</h1>
            <p className="text-slate-400">Monitoramento em tempo real do programa de CTI.</p>
          </div>
          <button 
            onClick={handleAiInsight}
            disabled={loadingAi}
            className="flex items-center gap-2 bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 px-4 py-2 rounded-lg font-medium transition-all shadow-lg shadow-indigo-900/20 disabled:opacity-50"
          >
            {loadingAi ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
