            <div className="mt-1"><Sparkles className="w-5 h-5 text-indigo-400" /></div>
            <p className="text-sm leading-relaxed">{aiInsight}</p>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
