import { GoogleGenAI } from "@google/genai";

export async function generateCTIInsight(prompt: string, context: string) {
  // Fix: Initializing GoogleGenAI according to guidelines, using process.env.API_KEY directly.
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Context: ${context}\n\nTask: ${prompt}`,
      config: {
        systemInstruction: "Você é um analista sênior de Cyber Threat Intelligence (CTI). Forneça análises táticas, operacionais ou estratégicas concisas e diretas baseadas nos dados fornecidos.",
        temperature: 0.7,
      }
    });

    // Correctly accessing .text property (not a method)
    return response.text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Falha ao gerar insights do analista virtual.";
  }
}

