          <button onClick={handleAiInsight} disabled={loadingAi} className="flex items-center gap-2 bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 px-4 py-2 rounded-lg font-medium transition-all shadow-lg shadow-indigo-900/20 disabled:opacity-50">
            {loadingAi ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />} Pedir Insight à IA
