              ))}
            </div>
          </nav>
        </div>
        <div className="p-4 border-t border-slate-800"><NavItem active={false} icon={<Settings className="w-4 h-4" />} label="Configurações" /></div>
      </aside>
      <main className="flex-1 flex flex-col min-w-0 bg-slate-950">
        <header className="h-16 border-b border-slate-800 px-6 flex items-center justify-between bg-slate-900/30 backdrop-blur-md sticky top-0 z-10">
          <div className="flex items-center gap-4">
            <button onClick={toggleSidebar} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors">{isSidebarOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}</button>
            <div className="h-4 w-px bg-slate-800"></div>
            <div className="flex items-center gap-2 text-sm">
              <span className="text-slate-500">Clientes</span>
              <ChevronRight className="w-3 h-3 text-slate-700" />
              <span className="text-slate-200 font-medium">{activeClient?.name}</span>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <div className="relative group">
              <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-indigo-400 transition-colors" />
              <input type="text" placeholder="Buscar IOCs, PIRs..." className="bg-slate-800/50 border border-slate-700 rounded-full py-1.5 pl-10 pr-4 text-sm focus:outline-none focus:border-indigo-500 transition-all w-64 focus:w-80" />
            </div>
            <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-indigo-500 to-purple-500 p-[2px] cursor-pointer hover:scale-105 transition-transform">
              <div className="w-full h-full rounded-full bg-slate-900 flex items-center justify-center text-[10px] font-bold">CTI</div>
            </div>
          </div>
        </header>
        <div className="flex-1 overflow-y-auto p-6 lg:p-10 scroll-smooth">
          {activePhase === 'dashboard' ? <Dashboard /> : <PhaseView phase={activePhase as CTIPhase} />}
        </div>
      </main>
    </div>
  );
}

