};

interface NavItemProps {
  active: boolean;
  onClick?: () => void;
  icon: React.ReactNode;
  label: string;
  color?: string;
  key?: React.Key;
}

function NavItem({ active, onClick, icon, label, color = 'indigo' }: NavItemProps) {
  const variant = COLOR_VARIANTS[color] || COLOR_VARIANTS.indigo;
  return (
    <button
      onClick={onClick}
      className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all group ${
        active 
          ? `${variant.bg} ${variant.text} border ${variant.border}` 
          : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'
      }`}
    >
      <div className={`${active ? variant.text : 'text-slate-500 group-hover:text-slate-300'}`}>
        {icon}
      </div>
      <span className="text-sm font-medium">{label}</span>
    </button>
  );
}

function StatCard({ title, value, color }: { title: string, value: string | number, color: string }) {
  const variant = COLOR_VARIANTS[color] || COLOR_VARIANTS.indigo;
  return (
    <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl hover:border-slate-700 transition-colors shadow-sm">
      <p className="text-xs font-bold text-slate-500 uppercase mb-2 tracking-widest">{title}</p>
      <div className="flex items-baseline gap-2">
        <span className={`text-3xl font-bold text-white`}>{value}</span>
        <div className={`w-2 h-2 rounded-full ${variant.dot} animate-pulse`}></div>
      </div>
    </div>
  );
}

export default function App() {
  const [clients, setClients] = useState<ClientData[]>(INITIAL_CLIENTS);
  const [activeClientId, setActiveClientId] = useState<string | null>(INITIAL_CLIENTS[0].id);
  const [activePhase, setActivePhase] = useState<CTIPhase | 'dashboard'>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [pirStatusFilter, setPirStatusFilter] = useState<'All' | 'Active' | 'Draft' | 'Archived'>('All');

  // State for PIR editing
  const [editingPir, setEditingPir] = useState<PIR | null>(null);

  const activeClient = useMemo(() => 
    clients.find(c => c.id === activeClientId) || null
  , [clients, activeClientId]);

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  // PIR Action handlers
  const handleUpdatePirStatus = (pirId: string, newStatus: PIR['status']) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(client => {
      if (client.id !== activeClientId) return client;
      return {
        ...client,
        phases: {
          ...client.phases,
          planning: {
            ...client.phases.planning,
            pirs: client.phases.planning.pirs.map(p => p.id === pirId ? { ...p, status: newStatus } : p)
          }
        }
      };
    }));
  };

  const handleSaveEditedPir = (updatedPir: PIR) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(client => {
      if (client.id !== activeClientId) return client;
      return {
        ...client,
        phases: {
          ...client.phases,
          planning: {
            ...client.phases.planning,
            pirs: client.phases.planning.pirs.map(p => p.id === updatedPir.id ? updatedPir : p)
          }
        }
      };
    }));
    setEditingPir(null);
  };

  const handleAiInsight = async () => {
    if (!activeClient) return;
    setLoadingAi(true);
    const context = JSON.stringify({
      client: activeClient.name,
      pirs: activeClient.phases.planning.pirs,
      iocs: activeClient.phases.collection.iocs.length,
      alerts: activeClient.phases.dissemination.alertsCount
    });
    const insight = await generateCTIInsight(
      "Com base nos dados deste cliente, sugira uma ação prioritária para o próximo ciclo de inteligência.",
      context
    );
    setAiInsight(insight);
    setLoadingAi(false);
  };

  const Dashboard = () => {
    if (!activeClient) return null;
    const chartData = [
      { name: 'Seg', alerts: 400, iocs: 240 },
      { name: 'Ter', alerts: 300, iocs: 139 },
      { name: 'Qua', alerts: 200, iocs: 980 },
      { name: 'Qui', alerts: 278, iocs: 390 },
      { name: 'Sex', alerts: 189, iocs: 480 },
      { name: 'Sab', alerts: 239, iocs: 380 },
      { name: 'Dom', alerts: 349, iocs: 430 },
    ];
    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-bold text-white mb-1">Visão Geral</h1>
            <p className="text-slate-400">Monitoramento em tempo real do programa de CTI.</p>
          </div>
          <button onClick={handleAiInsight} disabled={loadingAi} className="flex items-center gap-2 bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 px-4 py-2 rounded-lg font-medium transition-all shadow-lg shadow-indigo-900/20 disabled:opacity-50">
            {loadingAi ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />} Pedir Insight à IA
          </button>
        </header>
        {aiInsight && (
          <div className="bg-slate-900/50 border border-indigo-500/30 p-4 rounded-xl text-indigo-100 flex gap-3 animate-in zoom-in-95 duration-300">
            <div className="mt-1"><Sparkles className="w-5 h-5 text-indigo-400" /></div>
            <p className="text-sm leading-relaxed">{aiInsight}</p>
          </div>
        )}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <StatCard title="PIRs Ativos" value={activeClient.phases.planning.pirs.filter(p => p.status === 'Active').length} color="blue" />
          <StatCard title="IOCs Coletados" value={activeClient.phases.collection.iocs.length} color="emerald" />
          <StatCard title="Relatórios Emitidos" value={activeClient.phases.analysis.reports.length} color="amber" />
          <StatCard title="Alertas Integrados" value={activeClient.phases.dissemination.alertsCount} color="purple" />
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 bg-slate-900/50 border border-slate-800 p-6 rounded-2xl">
