                  <Area type="monotone" dataKey="alerts" stroke="#6366f1" fillOpacity={1} fill="url(#colorAlerts)" strokeWidth={2} />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </div>
          <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl">
            <h3 className="text-lg font-semibold mb-6">IOCs por Tipo</h3>
            <div className="space-y-4">
              {['IP', 'Domain', 'Hash', 'URL'].map(type => (
                <div key={type} className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-2 h-2 rounded-full bg-indigo-500"></div>
                    <span className="text-slate-300 font-medium">{type}</span>
                  </div>
                  <span className="text-slate-100 font-mono">{activeClient.phases.collection.iocs.filter(i => i.type === type).length}</span>
                </div>
              ))}
            </div>
            <div className="mt-8 pt-8 border-t border-slate-800">
              <h4 className="text-sm font-semibold text-slate-500 uppercase tracking-wider mb-4">Top Sources</h4>
              <div className="flex flex-wrap gap-2">
                {activeClient.phases.collection.sources.map(s => (
                  <span key={s} className="px-2 py-1 bg-slate-800 rounded text-xs text-slate-300">{s}</span>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  };

