            <button 
              onClick={() => onSave(edited)}
              className="bg-indigo-600 hover:bg-indigo-500 text-white px-5 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all shadow-lg shadow-indigo-900/20"
            >
              <Save className="w-4 h-4" /> Salvar Alterações
            </button>
          </div>
        </div>
      </div>
    );
  };

  const PhaseView = ({ phase }: { phase: CTIPhase }) => {
    const config = PHASE_CONFIG[phase];
    if (!activeClient) return null;
    const filteredPirs = useMemo(() => {
      if (pirStatusFilter === 'All') return activeClient.phases.planning.pirs;
      return activeClient.phases.planning.pirs.filter(pir => pir.status === pirStatusFilter);
    }, [activeClient.phases.planning.pirs, pirStatusFilter]);

    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500">
        <header className="mb-8">
          <div className="flex items-center gap-3 mb-2">
            <div className={`p-2 bg-${config.color}-500/20 text-${config.color}-400 rounded-lg`}>{config.icon}</div>
            <h1 className="text-3xl font-bold text-white">{config.title}</h1>
          </div>
          <p className="text-slate-400">Gerenciamento operacional da fase de {config.title.toLowerCase()}.</p>
        </header>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="md:col-span-3 space-y-6">
            <div className="bg-slate-900/50 border border-slate-800 rounded-2xl overflow-hidden">
              <div className="px-6 py-4 border-b border-slate-800 flex flex-wrap gap-4 justify-between items-center bg-slate-800/20">
                <div className="flex items-center gap-4">
                   <h3 className="font-semibold shrink-0">Registros da Fase</h3>
                   {phase === 'planning' && (
                     <div className="flex items-center gap-1 bg-slate-900/50 p-1 rounded-lg border border-slate-700/50">
                        {['All', 'Active', 'Draft', 'Archived'].map((status) => (
                          <button key={status} onClick={() => setPirStatusFilter(status as any)} className={`px-3 py-1 rounded-md text-[11px] font-bold uppercase tracking-wider transition-all ${pirStatusFilter === status ? 'bg-indigo-600 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                            {status === 'All' ? 'Todos' : status}
                          </button>
                        ))}
                     </div>
                   )}
                </div>
                <button className="text-indigo-400 hover:text-indigo-300 text-sm flex items-center gap-1 font-medium bg-indigo-400/10 px-3 py-1.5 rounded-lg border border-indigo-400/20 transition-all active:scale-95">
                  <Plus className="w-4 h-4" /> Novo Registro
                </button>
              </div>
              <div className="p-6">
                {phase === 'planning' && (
                  <div className="space-y-4">
                    {filteredPirs.length > 0 ? (
                      filteredPirs.map(pir => (
                        <div key={pir.id} className="p-4 bg-slate-800/50 rounded-xl border border-slate-700 hover:border-indigo-500/50 transition-all group relative">
                          <div className="flex justify-between mb-2">
                            <h4 className="font-bold text-slate-100 group-hover:text-indigo-400 transition-colors pr-24">{pir.title}</h4>
                            <div className="flex gap-2">
                               <span className={`text-[10px] px-2 py-0.5 rounded uppercase font-bold border ${
                                 pir.priority === 'High' ? 'bg-rose-500/20 text-rose-400 border-rose-500/30' : 
                                 pir.priority === 'Medium' ? 'bg-amber-500/20 text-amber-400 border-amber-500/30' :
                                 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30'
                               }`}>{pir.priority}</span>
                               <span className={`text-[10px] px-2 py-0.5 rounded uppercase font-bold border ${
                                 pir.status === 'Active' ? 'bg-indigo-500/20 text-indigo-400 border-indigo-500/30' :
                                 pir.status === 'Draft' ? 'bg-slate-500/20 text-slate-400 border-slate-500/30' :
                                 'bg-slate-700/50 text-slate-500 border-slate-600/30'
                               }`}>{pir.status}</span>
                            </div>
                          </div>
                          <p className="text-sm text-slate-400 mb-4 line-clamp-2">{pir.description}</p>

                          {/* Actions Row */}
                          <div className="flex items-center justify-between pt-3 border-t border-slate-800 mt-2">
                            <span className="text-[10px] text-slate-600 font-mono">ID: {pir.id}</span>
                            <div className="flex items-center gap-2">
                              {/* Edit Button with Visual Highlight on Card Hover */}
                              <button 
                                onClick={() => setEditingPir(pir)}
                                title="Editar PIR"
                                className="p-1.5 bg-slate-800/0 hover:bg-slate-700 rounded-md text-slate-500 group-hover:text-slate-200 hover:text-indigo-400 transition-all transform hover:scale-110 active:scale-95"
                              >
                                <Edit2 className="w-3.5 h-3.5" />
                              </button>

                              {/* Archive / Restore Toggle with Visual Highlight on Card Hover */}
                              {pir.status === 'Archived' ? (
                                <button 
                                  onClick={() => handleUpdatePirStatus(pir.id, 'Draft')}
