  const Section = ({ icon, title, items, color }: { icon: React.ReactNode, title: string, items: string[], color: string }) => (
    <div>
      <h5 className={`text-${color}-400 text-[10px] font-bold uppercase mb-2 flex items-center gap-1`}>{icon} {title}</h5>
      <ul className="space-y-1.5">
        {items.map(item => (
          <li key={item} className="text-sm text-slate-300 flex items-start gap-2">
            <div className="w-1.5 h-1.5 rounded-full bg-slate-700 mt-1.5 shrink-0"></div> {item}
