  const getCurrentTimestamp = () => {
    return new Date().toLocaleString('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  // PIR Action handlers
  const handleUpdatePirStatus = (pirId: string, newStatus: PIR['status']) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(client => {
      if (client.id !== activeClientId) return client;
      return {
        ...client,
        phases: {
          ...client.phases,
          planning: {
            ...client.phases.planning,
            pirs: client.phases.planning.pirs.map(p => {
              if (p.id === pirId) {
                const history = p.history || [];
                return { 
                  ...p, 
                  status: newStatus,
                  history: [...history, { status: newStatus, date: getCurrentTimestamp(), action: 'Status Changed' }]
                };
              }
              return p;
            })
          }
        }
      };
    }));
  };

  const handleSaveEditedPir = (updatedPir: PIR) => {
    if (!activeClientId || !activeClient) return;

    const originalPir = activeClient.phases.planning.pirs.find(p => p.id === updatedPir.id);
    const history = updatedPir.history || [];

    // Log if status changed during edit
    if (originalPir && originalPir.status !== updatedPir.status) {
      history.push({ status: updatedPir.status, date: getCurrentTimestamp(), action: 'Status Changed' });
    } else {
      history.push({ status: updatedPir.status, date: getCurrentTimestamp(), action: 'Edited' });
    }

    setClients(prev => prev.map(client => {
      if (client.id !== activeClientId) return client;
      return {
        ...client,
        phases: {
          ...client.phases,
          planning: {
            ...client.phases.planning,
            pirs: client.phases.planning.pirs.map(p => p.id === updatedPir.id ? { ...updatedPir, history } : p)
          }
        }
      };
    }));
    setEditingPir(null);
  };

