interface NavItemProps {
  active: boolean;
  onClick?: () => void;
  icon: React.ReactNode;
  label: string;
  color?: string;
  key?: React.Key;
}

function NavItem({ active, onClick, icon, label, color = 'indigo' }: NavItemProps) {
  const variant = COLOR_VARIANTS[color] || COLOR_VARIANTS.indigo;
  return (
    <button
      onClick={onClick}
      className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all group ${
        active 
          ? `${variant.bg} ${variant.text} border ${variant.border}` 
          : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'
      }`}
    >
      <div className={`${active ? variant.text : 'text-slate-500 group-hover:text-slate-300'}`}>
        {icon}
      </div>
      <span className="text-sm font-medium">{label}</span>
    </button>
  );
}

function StatCard({ title, value, color }: { title: string, value: string | number, color: string }) {
  const variant = COLOR_VARIANTS[color] || COLOR_VARIANTS.indigo;
  return (
    <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl hover:border-slate-700 transition-colors shadow-sm">
      <p className="text-xs font-bold text-slate-500 uppercase mb-2 tracking-widest">{title}</p>
