          </li>
        ))}
      </ul>
    </div>
  );

  return (
    <div className="flex h-screen w-full overflow-hidden">
      {editingPir && (
        <EditPirModal 
          pir={editingPir} 
          onSave={handleSaveEditedPir} 
          onClose={() => setEditingPir(null)} 
        />
      )}

      {viewingPirDetails && (
        <PirDetailsModal 
          pir={viewingPirDetails} 
          onClose={() => setViewingPirDetails(null)} 
        />
      )}

      <aside className={`bg-slate-900 border-r border-slate-800 transition-all duration-300 flex flex-col ${isSidebarOpen ? 'w-64' : 'w-0 overflow-hidden'}`}>
