            <div className="space-y-1">
              {clients.map(client => (
                <button key={client.id} onClick={() => { setActiveClientId(client.id); setPirStatusFilter('All'); }} className={`w-full flex items-center justify-between px-3 py-2 rounded-lg transition-all ${activeClientId === client.id ? 'bg-indigo-500/10 text-indigo-400 border border-indigo-500/20' : 'text-slate-400 hover:bg-slate-800'}`}>
                  <span className="font-medium truncate">{client.name}</span>
                  {activeClientId === client.id && <div className="w-1.5 h-1.5 rounded-full bg-indigo-500"></div>}
                </button>
              ))}
              <button className="w-full mt-2 flex items-center gap-2 px-3 py-2 text-slate-500 hover:text-slate-300 text-sm italic"><Plus className="w-4 h-4" /> Adicionar Cliente</button>
            </div>
          </div>
          <nav>
            <label className="text-[10px] font-bold text-slate-500 uppercase px-2 mb-3 block">Menu Principal</label>
            <div className="space-y-1">
              <NavItem active={activePhase === 'dashboard'} onClick={() => setActivePhase('dashboard')} icon={<LayoutDashboard className="w-4 h-4" />} label="Dashboard" />
            </div>
            <label className="text-[10px] font-bold text-slate-500 uppercase px-2 mt-8 mb-3 block">Ciclo de Vida (Fases)</label>
            <div className="space-y-1">
              {(Object.keys(PHASE_CONFIG) as CTIPhase[]).map(phaseKey => (
                <NavItem key={phaseKey} active={activePhase === phaseKey} onClick={() => setActivePhase(phaseKey)} icon={PHASE_CONFIG[phaseKey].icon} label={PHASE_CONFIG[phaseKey].title.split(' ')[0]} color={PHASE_CONFIG[phaseKey].color} />
              ))}
            </div>
          </nav>
        </div>
        <div className="p-4 border-t border-slate-800"><NavItem active={false} icon={<Settings className="w-4 h-4" />} label="Configurações" /></div>
      </aside>
      <main className="flex-1 flex flex-col min-w-0 bg-slate-950">
        <header className="h-16 border-b border-slate-800 px-6 flex items-center justify-between bg-slate-900/30 backdrop-blur-md sticky top-0 z-10">
          <div className="flex items-center gap-4">
            <button onClick={toggleSidebar} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors">{isSidebarOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}</button>
            <div className="h-4 w-px bg-slate-800"></div>
            <div className="flex items-center gap-2 text-sm">
              <span className="text-slate-500">Clientes</span>
              <ChevronRight className="w-3 h-3 text-slate-700" />
              <span className="text-slate-200 font-medium">{activeClient?.name}</span>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <div className="relative group">
              <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-indigo-400 transition-colors" />
              <input type="text" placeholder="Buscar IOCs, PIRs..." className="bg-slate-800/50 border border-slate-700 rounded-full py-1.5 pl-10 pr-4 text-sm focus:outline-none focus:border-indigo-500 transition-all w-64 focus:w-80" />
            </div>
            <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-indigo-500 to-purple-500 p-[2px] cursor-pointer hover:scale-105 transition-transform">
              <div className="w-full h-full rounded-full bg-slate-900 flex items-center justify-center text-[10px] font-bold">CTI</div>
            </div>
          </div>
        </header>
        <div className="flex-1 overflow-y-auto p-6 lg:p-10 scroll-smooth">
          {activePhase === 'dashboard' ? <Dashboard /> : <PhaseView phase={activePhase as CTIPhase} />}
        </div>
      </main>
    </div>
  );
}

export type CTIPhase = 'planning' | 'collection' | 'analysis' | 'dissemination' | 'feedback' | 'metrics';

export interface StatusHistory {
  status: string;
  date: string;
  action: 'Created' | 'Status Changed' | 'Edited';
}

export interface PIR {
  id: string;
  title: string;
  description: string;
  priority: 'High' | 'Medium' | 'Low';
  status: 'Active' | 'Draft' | 'Archived';
  history?: StatusHistory[];
}

export interface IntelligenceSource {
  id: string;
  name: string;
  type: 'Internal' | 'OSINT' | 'Commercial' | 'DarkWeb';
  confidence: number; // 0-100 (OpenCTI standard)
  integrationDate: string;
  reliability: 'A' | 'B' | 'C' | 'D' | 'E' | 'F'; // Admiralty Scale
}

export interface MetricRecord {
  id: string;
  pirId: string;
  incidentDate: string;
  discoveryDate: string;
  disseminationDate: string;
  wasPreviouslyReported: boolean;
  incidentPrevented: boolean;
  impactScale: 'Low' | 'Medium' | 'High' | 'Critical';
}

export interface Report {
  id: string;
  title: string;
  type: 'Strategic' | 'Operational' | 'Tactical';
  content: string;
  date: string;
}

export interface KPI {
  name: string;
  value: number;
  unit: string;
}

export interface ClientData {
  id: string;
  name: string;
  sector: string;
  phases: {
    planning: { pirs: PIR[]; stakeholders: string[] };
    collection: { sources: IntelligenceSource[] };
    analysis: { reports: Report[]; ttps: string[] };
    dissemination: { integrations: string[]; alertsCount: number };
    feedback: { kpis: KPI[]; improvements: string[] };
  };
  metrics: MetricRecord[];
}

export interface AppState {
  clients: ClientData[];
  activeClientId: string | null;
}

