export default function App() {
  const [clients, setClients] = useState<ClientData[]>(INITIAL_CLIENTS);
  const [activeClientId, setActiveClientId] = useState<string | null>(INITIAL_CLIENTS[0].id);
  const [activePhase, setActivePhase] = useState<CTIPhase | 'dashboard' | 'metrics'>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [pirStatusFilter, setPirStatusFilter] = useState<'All' | 'Active' | 'Draft' | 'Archived'>('All');

  const [editingPir, setEditingPir] = useState<PIR | null>(null);
  const [viewingPirDetails, setViewingPirDetails] = useState<PIR | null>(null);
  const [isMetricModalOpen, setIsMetricModalOpen] = useState(false);

  const activeClient = useMemo(() => 
    clients.find(c => c.id === activeClientId) || null
  , [clients, activeClientId]);

  // Derived Performance Metrics
  const performanceStats = useMemo(() => {
    if (!activeClient || activeClient.metrics.length === 0) return null;

    const diffHours = (d1: string, d2: string) => {
      const ms = new Date(d1).getTime() - new Date(d2).getTime();
      return Math.max(0, ms / (1000 * 60 * 60));
    };

    const mttd = activeClient.metrics.reduce((acc, m) => acc + diffHours(m.discoveryDate, m.incidentDate), 0) / activeClient.metrics.length;
    const mttdis = activeClient.metrics.reduce((acc, m) => acc + diffHours(m.disseminationDate, m.discoveryDate), 0) / activeClient.metrics.length;

    const reportedCount = activeClient.metrics.filter(m => m.wasPreviouslyReported).length;
    const preventedCount = activeClient.metrics.filter(m => m.incidentPrevented).length;

    return {
      mttd: mttd.toFixed(1),
      mttdis: mttdis.toFixed(1),
      accuracy: ((reportedCount / activeClient.metrics.length) * 100).toFixed(0),
      prevention: ((preventedCount / activeClient.metrics.length) * 100).toFixed(0),
      totalIncidents: activeClient.metrics.length
    };
  }, [activeClient]);

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  const handleAddMetric = (newMetric: Omit<MetricRecord, 'id'>) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => c.id === activeClientId ? {
      ...c,
      metrics: [...c.metrics, { ...newMetric, id: Math.random().toString(36).substr(2, 9) }]
    } : c));
    setIsMetricModalOpen(false);
  };

  const Dashboard = () => {
    if (!activeClient) return null;
    const metricsData = performanceStats ? [
      { name: 'MTTD (h)', value: parseFloat(performanceStats.mttd) },
      { name: 'MTTDis (h)', value: parseFloat(performanceStats.mttdis) },
    ] : [];

    const accuracyData = performanceStats ? [
      { name: 'Precisão', value: parseFloat(performanceStats.accuracy), color: '#6366f1' },
      { name: 'Prevenção', value: parseFloat(performanceStats.prevention), color: '#10b981' }
    ] : [];

    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-bold text-white mb-1">Visão Geral</h1>
            <p className="text-slate-400">Desempenho e ROI do programa de CTI para {activeClient.name}.</p>
          </div>
          <button onClick={() => setIsMetricModalOpen(true)} className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 px-4 py-2 rounded-lg font-medium transition-all border border-slate-700">
            <Plus className="w-4 h-4" /> Registrar Caso
          </button>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <StatCard title="MTTD Médio" value={performanceStats ? `${performanceStats.mttd}h` : 'N/A'} color="blue" />
          <StatCard title="MTTDis Médio" value={performanceStats ? `${performanceStats.mttdis}h` : 'N/A'} color="purple" />
          <StatCard title="Taxa de Precisão" value={performanceStats ? `${performanceStats.accuracy}%` : 'N/A'} color="emerald" />
          <StatCard title="Taxa de Prevenção" value={performanceStats ? `${performanceStats.prevention}%` : 'N/A'} color="rose" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl">
            <h3 className="text-lg font-semibold mb-6 flex items-center gap-2">
              <Activity className="w-5 h-5 text-indigo-400" /> Latência de Inteligência
            </h3>
            <div className="h-[250px]">
              <ResponsiveContainer width="100%" height="100%">
                <ReBarChart data={metricsData} layout="vertical">
                  <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" horizontal={true} vertical={false} />
                  <XAxis type="number" stroke="#64748b" fontSize={12} />
                  <YAxis dataKey="name" type="category" stroke="#64748b" fontSize={12} />
                  <Tooltip cursor={{fill: '#1e293b'}} contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155' }} />
                  <Bar dataKey="value" fill="#6366f1" radius={[0, 4, 4, 0]} barSize={40} />
                </ReBarChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-4 text-xs text-slate-500 italic">
              * MTTD: Tempo entre incidente e descoberta. MTTDis: Tempo entre descoberta e disseminação.
            </p>
          </div>

          <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl">
            <h3 className="text-lg font-semibold mb-6 flex items-center gap-2">
              <Shield className="w-5 h-5 text-emerald-400" /> Eficácia de Detecção & Prevenção
            </h3>
            <div className="h-[250px]">
              <ResponsiveContainer width="100%" height="100%">
                <ReBarChart data={accuracyData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                  <XAxis dataKey="name" stroke="#64748b" fontSize={12} />
                  <YAxis stroke="#64748b" fontSize={12} unit="%" />
                  <Tooltip contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155' }} />
                  <Bar dataKey="value" radius={[4, 4, 0, 0]} barSize={60}>
                    {accuracyData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.color} />
                    ))}
                  </Bar>
                </ReBarChart>
              </ResponsiveContainer>
            </div>
            <div className="flex justify-around mt-4">
              <div className="text-center">
                <span className="block text-xl font-bold text-indigo-400">{performanceStats?.accuracy}%</span>
                <span className="text-[10px] text-slate-500 uppercase font-bold">Ameaças Antecipadas</span>
              </div>
              <div className="text-center">
                <span className="block text-xl font-bold text-emerald-400">{performanceStats?.prevention}%</span>
                <span className="text-[10px] text-slate-500 uppercase font-bold">Incidentes Bloqueados</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  };

  const MetricEntryModal = () => {
    const [form, setForm] = useState<Omit<MetricRecord, 'id'>>({
      pirId: activeClient?.phases.planning.pirs[0]?.id || '',
      incidentDate: '',
      discoveryDate: '',
      disseminationDate: '',
      wasPreviouslyReported: false,
      incidentPrevented: false,
      impactScale: 'Medium'
    });

    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
        <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-sm" onClick={() => setIsMetricModalOpen(false)} />
        <div className="relative bg-slate-900 border border-slate-800 w-full max-w-xl rounded-2xl shadow-2xl overflow-hidden">
          <div className="px-6 py-4 border-b border-slate-800 flex justify-between items-center bg-slate-800/20">
            <h3 className="font-bold text-lg flex items-center gap-2"><BarChart className="w-5 h-5 text-indigo-400" /> Registro de Caso de Inteligência</h3>
            <button onClick={() => setIsMetricModalOpen(false)} className="text-slate-500 hover:text-white"><X className="w-6 h-6" /></button>
          </div>
          <div className="p-6 space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">PIR Relacionado</label>
                <select value={form.pirId} onChange={e => setForm({...form, pirId: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm">
                  {activeClient?.phases.planning.pirs.map(p => <option key={p.id} value={p.id}>{p.title}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Escala de Impacto</label>
                <select value={form.impactScale} onChange={e => setForm({...form, impactScale: e.target.value as any})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm">
                  <option value="Low">Baixo</option>
                  <option value="Medium">Médio</option>
                  <option value="High">Alto</option>
                  <option value="Critical">Crítico</option>
                </select>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Data Incidente</label>
                <input type="datetime-local" value={form.incidentDate} onChange={e => setForm({...form, incidentDate: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Data Descoberta</label>
                <input type="datetime-local" value={form.discoveryDate} onChange={e => setForm({...form, discoveryDate: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Data Disseminação</label>
                <input type="datetime-local" value={form.disseminationDate} onChange={e => setForm({...form, disseminationDate: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white" />
              </div>
            </div>
            <div className="flex gap-6 pt-4">
              <label className="flex items-center gap-2 cursor-pointer">
                <input type="checkbox" checked={form.wasPreviouslyReported} onChange={e => setForm({...form, wasPreviouslyReported: e.target.checked})} className="w-4 h-4 rounded bg-slate-950 border-slate-800 text-indigo-600 focus:ring-indigo-500" />
                <span className="text-sm text-slate-300">Já constava em relatórios?</span>
              </label>
              <label className="flex items-center gap-2 cursor-pointer">
                <input type="checkbox" checked={form.incidentPrevented} onChange={e => setForm({...form, incidentPrevented: e.target.checked})} className="w-4 h-4 rounded bg-slate-950 border-slate-800 text-emerald-600 focus:ring-emerald-500" />
                <span className="text-sm text-slate-300">Incidente prevenido?</span>
              </label>
            </div>
          </div>
          <div className="px-6 py-4 bg-slate-800/20 border-t border-slate-800 flex justify-end gap-3">
            <button onClick={() => setIsMetricModalOpen(false)} className="text-sm text-slate-400 font-medium">Cancelar</button>
            <button onClick={() => handleAddMetric(form)} className="bg-indigo-600 hover:bg-indigo-500 text-white px-6 py-2 rounded-xl text-sm font-bold transition-all shadow-lg shadow-indigo-900/20">Salvar Registro</button>
          </div>
        </div>
      </div>
    );
  };

  const PhaseView = ({ phase }: { phase: CTIPhase }) => {
    const config = PHASE_CONFIG[phase];
    if (!activeClient) return null;

    const phaseIndex = PHASE_ORDER.indexOf(phase);
    const prevPhase = phaseIndex > 0 ? PHASE_ORDER[phaseIndex - 1] : null;
    const nextPhase = phaseIndex < PHASE_ORDER.length - 1 ? PHASE_ORDER[phaseIndex + 1] : null;

    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500 pb-20">
