              <Sparkles className="w-4 h-4" /> Insight IA
            </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 lg:p-10">
          {aiInsight && (
            <div className="mb-8 p-4 bg-indigo-600/10 border border-indigo-500/30 rounded-xl flex gap-3 animate-in zoom-in-95">
              <Sparkles className="w-5 h-5 text-indigo-400 mt-1" />
              <p className="text-sm text-indigo-100">{aiInsight}</p>
            </div>
          )}
          {activePhase === 'dashboard' ? <Dashboard /> : <PhaseView phase={activePhase as CTIPhase} />}
        </div>
      </main>
    </div>
  );
}

