export default function App() {
  const [clients, setClients] = useState<ClientData[]>(INITIAL_CLIENTS);
  const [activeClientId, setActiveClientId] = useState<string | null>(INITIAL_CLIENTS[0].id);
  const [activePhase, setActivePhase] = useState<CTIPhase | 'dashboard' | 'metrics'>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [pirStatusFilter, setPirStatusFilter] = useState<'All' | 'Active' | 'Draft' | 'Archived'>('All');

  const [editingPir, setEditingPir] = useState<PIR | null>(null);
  const [viewingPirDetails, setViewingPirDetails] = useState<PIR | null>(null);
  const [isMetricModalOpen, setIsMetricModalOpen] = useState(false);

  const activeClient = useMemo(() => 
    clients.find(c => c.id === activeClientId) || null
  , [clients, activeClientId]);

  // Derived Performance Metrics
  const performanceStats = useMemo(() => {
    if (!activeClient || activeClient.metrics.length === 0) return null;

    const diffHours = (d1: string, d2: string) => {
      const ms = new Date(d1).getTime() - new Date(d2).getTime();
      return Math.max(0, ms / (1000 * 60 * 60));
    };

    const mttd = activeClient.metrics.reduce((acc, m) => acc + diffHours(m.discoveryDate, m.incidentDate), 0) / activeClient.metrics.length;
    const mttdis = activeClient.metrics.reduce((acc, m) => acc + diffHours(m.disseminationDate, m.discoveryDate), 0) / activeClient.metrics.length;

    const reportedCount = activeClient.metrics.filter(m => m.wasPreviouslyReported).length;
    const preventedCount = activeClient.metrics.filter(m => m.incidentPrevented).length;

    return {
      mttd: mttd.toFixed(1),
      mttdis: mttdis.toFixed(1),
      accuracy: ((reportedCount / activeClient.metrics.length) * 100).toFixed(0),
      prevention: ((preventedCount / activeClient.metrics.length) * 100).toFixed(0),
      totalIncidents: activeClient.metrics.length
    };
  }, [activeClient]);

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  // Fix: Implemented handleAiInsight to resolve 'Cannot find name handleAiInsight' error
  // This function collects context from the active client and phase to generate a Gemini AI insight.
  const handleAiInsight = async () => {
    if (!activeClient) return;
    setLoadingAi(true);
    setAiInsight(null);
    try {
      const context = `Cliente: ${activeClient.name} (${activeClient.sector}). 
                       Fase Atual: ${activePhase}. 
                       PIRs Ativos: ${activeClient.phases.planning.pirs.filter(p => p.status === 'Active').length}. 
                       Fontes de Coleta: ${activeClient.phases.collection.sources.map(s => s.name).join(', ')}. 
                       Métricas de Desempenho - MTTD: ${performanceStats?.mttd || 'N/A'}h, Precisão: ${performanceStats?.accuracy || 'N/A'}%.`;

      const prompt = activePhase === 'dashboard' 
        ? "Como um analista sênior de CTI, forneça uma análise estratégica concisa do desempenho atual deste cliente e recomende uma prioridade tática para o próximo ciclo." 
        : `Analise a fase operacional de "${activePhase}" para este cliente de CTI. Identifique potenciais lacunas de visibilidade e sugira uma melhoria prática.`;

      const result = await generateCTIInsight(prompt, context);
      setAiInsight(result || "Não foi possível gerar um insight no momento.");
    } catch (error) {
      console.error("AI Insight Error:", error);
      setAiInsight("Ocorreu um erro ao processar o insight do analista virtual. Verifique a chave de API.");
    } finally {
      setLoadingAi(false);
    }
  };

  const handleAddMetric = (newMetric: Omit<MetricRecord, 'id'>) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => c.id === activeClientId ? {
      ...c,
      metrics: [...c.metrics, { ...newMetric, id: Math.random().toString(36).substr(2, 9) }]
    } : c));
    setIsMetricModalOpen(false);
  };

  const Dashboard = () => {
    if (!activeClient) return null;
    const metricsData = performanceStats ? [
      { name: 'MTTD (h)', value: parseFloat(performanceStats.mttd) },
      { name: 'MTTDis (h)', value: parseFloat(performanceStats.mttdis) },
    ] : [];

    const accuracyData = performanceStats ? [
      { name: 'Precisão', value: parseFloat(performanceStats.accuracy), color: '#6366f1' },
      { name: 'Prevenção', value: parseFloat(performanceStats.prevention), color: '#10b981' }
    ] : [];

    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-bold text-white mb-1">Visão Geral</h1>
            <p className="text-slate-400">Desempenho e ROI do programa de CTI para {activeClient.name}.</p>
          </div>
          <button onClick={() => setIsMetricModalOpen(true)} className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 px-4 py-2 rounded-lg font-medium transition-all border border-slate-700">
            <Plus className="w-4 h-4" /> Registrar Caso
          </button>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <StatCard title="MTTD Médio" value={performanceStats ? `${performanceStats.mttd}h` : 'N/A'} color="blue" />
          <StatCard title="MTTDis Médio" value={performanceStats ? `${performanceStats.mttdis}h` : 'N/A'} color="purple" />
          <StatCard title="Taxa de Precisão" value={performanceStats ? `${performanceStats.accuracy}%` : 'N/A'} color="emerald" />
          <StatCard title="Taxa de Prevenção" value={performanceStats ? `${performanceStats.prevention}%` : 'N/A'} color="rose" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl">
