                  <YAxis dataKey="name" type="category" stroke="#64748b" fontSize={12} />
                  <Tooltip cursor={{fill: '#1e293b'}} contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155' }} />
                  <Bar dataKey="value" fill="#6366f1" radius={[0, 4, 4, 0]} barSize={40} />
                </ReBarChart>
              </ResponsiveContainer>
