                </ReBarChart>
              </ResponsiveContainer>
            </div>
            <div className="flex justify-around mt-4">
              <div className="text-center">
                <span className="block text-xl font-bold text-indigo-400">{performanceStats?.accuracy}%</span>
                <span className="text-[10px] text-slate-500 uppercase font-bold">Ameaças Antecipadas</span>
              </div>
              <div className="text-center">
                <span className="block text-xl font-bold text-emerald-400">{performanceStats?.prevention}%</span>
                <span className="text-[10px] text-slate-500 uppercase font-bold">Incidentes Bloqueados</span>
              </div>
            </div>
          </div>
