  };

  const MetricEntryModal = () => {
    const [form, setForm] = useState<Omit<MetricRecord, 'id'>>({
      pirId: activeClient?.phases.planning.pirs[0]?.id || '',
      incidentDate: '',
      discoveryDate: '',
      disseminationDate: '',
      wasPreviouslyReported: false,
      incidentPrevented: false,
      impactScale: 'Medium'
    });

    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
        <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-sm" onClick={() => setIsMetricModalOpen(false)} />
        <div className="relative bg-slate-900 border border-slate-800 w-full max-w-xl rounded-2xl shadow-2xl overflow-hidden">
          <div className="px-6 py-4 border-b border-slate-800 flex justify-between items-center bg-slate-800/20">
            <h3 className="font-bold text-lg flex items-center gap-2"><BarChart className="w-5 h-5 text-indigo-400" /> Registro de Caso de Inteligência</h3>
            <button onClick={() => setIsMetricModalOpen(false)} className="text-slate-500 hover:text-white"><X className="w-6 h-6" /></button>
          </div>
          <div className="p-6 space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">PIR Relacionado</label>
                <select value={form.pirId} onChange={e => setForm({...form, pirId: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm">
                  {activeClient?.phases.planning.pirs.map(p => <option key={p.id} value={p.id}>{p.title}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Escala de Impacto</label>
                <select value={form.impactScale} onChange={e => setForm({...form, impactScale: e.target.value as any})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm">
                  <option value="Low">Baixo</option>
                  <option value="Medium">Médio</option>
                  <option value="High">Alto</option>
                  <option value="Critical">Crítico</option>
                </select>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Data Incidente</label>
                <input type="datetime-local" value={form.incidentDate} onChange={e => setForm({...form, incidentDate: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Data Descoberta</label>
                <input type="datetime-local" value={form.discoveryDate} onChange={e => setForm({...form, discoveryDate: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Data Disseminação</label>
                <input type="datetime-local" value={form.disseminationDate} onChange={e => setForm({...form, disseminationDate: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white" />
              </div>
            </div>
            <div className="flex gap-6 pt-4">
              <label className="flex items-center gap-2 cursor-pointer">
                <input type="checkbox" checked={form.wasPreviouslyReported} onChange={e => setForm({...form, wasPreviouslyReported: e.target.checked})} className="w-4 h-4 rounded bg-slate-950 border-slate-800 text-indigo-600 focus:ring-indigo-500" />
                <span className="text-sm text-slate-300">Já constava em relatórios?</span>
              </label>
              <label className="flex items-center gap-2 cursor-pointer">
                <input type="checkbox" checked={form.incidentPrevented} onChange={e => setForm({...form, incidentPrevented: e.target.checked})} className="w-4 h-4 rounded bg-slate-950 border-slate-800 text-emerald-600 focus:ring-emerald-500" />
                <span className="text-sm text-slate-300">Incidente prevenido?</span>
              </label>
            </div>
          </div>
          <div className="px-6 py-4 bg-slate-800/20 border-t border-slate-800 flex justify-end gap-3">
            <button onClick={() => setIsMetricModalOpen(false)} className="text-sm text-slate-400 font-medium">Cancelar</button>
            <button onClick={() => handleAddMetric(form)} className="bg-indigo-600 hover:bg-indigo-500 text-white px-6 py-2 rounded-xl text-sm font-bold transition-all shadow-lg shadow-indigo-900/20">Salvar Registro</button>
          </div>
        </div>
      </div>
    );
  };

  const PhaseView = ({ phase }: { phase: CTIPhase }) => {
    const config = PHASE_CONFIG[phase];
    if (!activeClient) return null;

    const phaseIndex = PHASE_ORDER.indexOf(phase);
    const prevPhase = phaseIndex > 0 ? PHASE_ORDER[phaseIndex - 1] : null;
    const nextPhase = phaseIndex < PHASE_ORDER.length - 1 ? PHASE_ORDER[phaseIndex + 1] : null;

    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500 pb-20">
        <header className="mb-8 flex justify-between items-start">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <div className={`p-2 bg-${config.color}-500/20 text-${config.color}-400 rounded-lg`}>{config.icon}</div>
              <h1 className="text-3xl font-bold text-white">{config.title}</h1>
            </div>
            <p className="text-slate-400">Gerenciamento operacional da fase de {config.title.toLowerCase()}.</p>
          </div>
          <div className="flex items-center gap-2 bg-slate-900/50 p-1 rounded-xl border border-slate-800">
             <button disabled={!prevPhase} onClick={() => setActivePhase(prevPhase!)} className="p-2 text-slate-500 hover:text-white disabled:opacity-20 transition-all rounded-lg"><ChevronLeft className="w-5 h-5" /></button>
             <button disabled={!nextPhase} onClick={() => setActivePhase(nextPhase!)} className="p-2 text-slate-500 hover:text-white disabled:opacity-20 transition-all rounded-lg"><ChevronRight className="w-5 h-5" /></button>
          </div>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="md:col-span-3 space-y-6">
            <div className="bg-slate-900/50 border border-slate-800 rounded-2xl overflow-hidden">
              <div className="px-6 py-4 border-b border-slate-800 flex flex-wrap gap-4 justify-between items-center bg-slate-800/20">
                <h3 className="font-semibold shrink-0">Registros da Fase</h3>
                <button className="text-indigo-400 hover:text-indigo-300 text-sm flex items-center gap-1 font-medium bg-indigo-400/10 px-3 py-1.5 rounded-lg border border-indigo-400/20 transition-all active:scale-95">
                  <Plus className="w-4 h-4" /> Novo Registro
                </button>
              </div>
              <div className="p-6">
                {phase === 'collection' ? (
                  <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm">
                      <thead>
                        <tr className="text-slate-500 border-b border-slate-800 uppercase tracking-wider text-[11px]">
                          <th className="pb-4 px-2">Fonte</th>
                          <th className="pb-4 px-2">Tipo</th>
                          <th className="pb-4 px-2">Confiança (STIX)</th>
                          <th className="pb-4 px-2 text-center">Confiabilidade</th>
                          <th className="pb-4 px-2 text-right">Integração</th>
                        </tr>
                      </thead>
                      <tbody>
                        {activeClient.phases.collection.sources.map(source => (
                          <tr key={source.id} className="border-b border-slate-800/50 hover:bg-slate-800/30 transition-colors group">
                            <td className="py-4 px-2 text-slate-100 font-bold">{source.name}</td>
                            <td className="py-4 px-2 text-slate-400"><span className="px-2 py-1 bg-slate-800 rounded text-[10px]">{source.type}</span></td>
                            <td className="py-4 px-2">
                               <div className="flex items-center gap-2">
                                  <div className="flex-1 h-1.5 bg-slate-800 rounded-full max-w-[100px] overflow-hidden">
                                     <div className={`h-full rounded-full ${source.confidence > 80 ? 'bg-emerald-500' : source.confidence > 50 ? 'bg-amber-500' : 'bg-rose-500'}`} style={{ width: `${source.confidence}%` }}></div>
                                  </div>
                                  <span className="text-xs font-mono">{source.confidence}</span>
                               </div>
                            </td>
                            <td className="py-4 px-2 text-center font-mono">
                               <span className="text-indigo-400 font-bold">{source.reliability}</span>
                            </td>
                            <td className="py-4 px-2 text-right text-slate-500 text-xs font-mono">{source.integrationDate}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                ) : phase === 'planning' ? (
                  <div className="space-y-4">
                    {activeClient.phases.planning.pirs.map(pir => (
                      <div key={pir.id} className="p-4 bg-slate-800/50 rounded-xl border border-slate-700 hover:border-indigo-500/50 transition-all group">
                         <div className="flex justify-between mb-2">
                            <h4 className="font-bold text-slate-100 group-hover:text-indigo-400">{pir.title}</h4>
                            <span className={`text-[10px] px-2 py-0.5 rounded uppercase font-bold border ${pir.priority === 'High' ? 'bg-rose-500/20 text-rose-400 border-rose-500/30' : 'bg-amber-500/20 text-amber-400 border-amber-500/30'}`}>{pir.priority}</span>
                         </div>
                         <p className="text-sm text-slate-400 line-clamp-2">{pir.description}</p>
                         <div className="mt-4 pt-4 border-t border-slate-800 flex justify-between items-center">
                            <span className="text-[10px] font-mono text-slate-600">ID: {pir.id}</span>
                            <button className="text-indigo-400 text-xs font-bold uppercase hover:underline">Detalhes</button>
                         </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="flex flex-col items-center justify-center py-20 text-slate-600">
                    <Database className="w-12 h-12 mb-4 opacity-20" />
                    <p>Processamento de fase {config.title} em andamento...</p>
                  </div>
                )}
              </div>
            </div>
          </div>
          <div className="space-y-6">
            <div className="bg-slate-900/80 border border-slate-800 rounded-2xl p-6 shadow-xl">
              <h4 className="text-xs font-bold text-slate-500 uppercase mb-4 tracking-widest border-b border-slate-800 pb-2">Contexto do Ciclo</h4>
              <div className="space-y-6">
                <div>
                  <h5 className="text-indigo-400 text-[10px] font-bold uppercase mb-2">Entradas</h5>
                  <ul className="space-y-1">
                    {config.inputs.map(i => <li key={i} className="text-xs text-slate-400 flex items-center gap-2"><div className="w-1 h-1 bg-slate-700 rounded-full" /> {i}</li>)}
                  </ul>
                </div>
                <div>
                  <h5 className="text-emerald-400 text-[10px] font-bold uppercase mb-2">Saídas</h5>
                  <ul className="space-y-1">
                    {config.outputs.map(o => <li key={o} className="text-xs text-slate-400 flex items-center gap-2"><div className="w-1 h-1 bg-slate-700 rounded-full" /> {o}</li>)}
                  </ul>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  };

  const NavItem = ({ active, onClick, icon, label, color = 'indigo' }: any) => {
    const variant = COLOR_VARIANTS[color] || COLOR_VARIANTS.indigo;
    return (
      <button onClick={onClick} className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all group ${active ? `${variant.bg} ${variant.text} border ${variant.border}` : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'}`}>
        <div className={`${active ? variant.text : 'text-slate-500 group-hover:text-slate-300'}`}>{icon}</div>
        <span className="text-sm font-medium">{label}</span>
      </button>
    );
  }

  const StatCard = ({ title, value, color }: any) => {
    const variant = COLOR_VARIANTS[color] || COLOR_VARIANTS.indigo;
    return (
      <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl hover:border-slate-700 transition-colors shadow-sm">
        <p className="text-xs font-bold text-slate-500 uppercase mb-2 tracking-widest">{title}</p>
        <span className="text-3xl font-bold text-white">{value}</span>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-950">
      {isMetricModalOpen && <MetricEntryModal />}

      <aside className={`bg-slate-900 border-r border-slate-800 transition-all duration-300 flex flex-col ${isSidebarOpen ? 'w-64' : 'w-0 overflow-hidden'}`}>
        <div className="p-6 flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-xl"><Shield className="w-6 h-6 text-white" /></div>
          <span className="font-bold text-xl text-white">CTI Sentinel</span>
        </div>
        <div className="px-4 py-6 flex-1 space-y-6 overflow-y-auto">
          <div>
            <label className="text-[10px] font-bold text-slate-500 uppercase px-2 mb-3 block">Cliente Ativo</label>
            <div className="space-y-1">
              {clients.map(client => (
                <button key={client.id} onClick={() => setActiveClientId(client.id)} className={`w-full text-left px-3 py-2 rounded-lg text-sm truncate ${activeClientId === client.id ? 'bg-indigo-500/10 text-indigo-400 border border-indigo-500/20' : 'text-slate-400 hover:bg-slate-800'}`}>
                  {client.name}
                </button>
              ))}
            </div>
          </div>
          <nav className="space-y-6">
            <div>
              <label className="text-[10px] font-bold text-slate-500 uppercase px-2 mb-3 block">Menu</label>
              <NavItem active={activePhase === 'dashboard'} onClick={() => setActivePhase('dashboard')} icon={<LayoutDashboard className="w-4 h-4" />} label="Dashboard" />
            </div>
            <div>
              <label className="text-[10px] font-bold text-slate-500 uppercase px-2 mb-3 block">Fases</label>
              {(Object.keys(PHASE_CONFIG) as CTIPhase[]).map(p => (
                <NavItem key={p} active={activePhase === p} onClick={() => setActivePhase(p)} icon={PHASE_CONFIG[p].icon} label={PHASE_CONFIG[p].title.split(' ')[0]} color={PHASE_CONFIG[p].color} />
              ))}
            </div>
          </nav>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0">
        <header className="h-16 border-b border-slate-800 px-6 flex items-center justify-between bg-slate-900/30 backdrop-blur-md sticky top-0 z-10">
          <div className="flex items-center gap-4">
            <button onClick={toggleSidebar} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors">{isSidebarOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}</button>
            <div className="flex items-center gap-2 text-sm">
              <span className="text-slate-500">Clientes</span>
              <ChevronRight className="w-3 h-3 text-slate-700" />
              <span className="text-slate-200 font-medium">{activeClient?.name}</span>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <button 
              disabled={loadingAi}
              className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 px-4 py-1.5 rounded-full text-sm font-medium transition-all disabled:opacity-50 min-w-[120px] justify-center" 
              onClick={handleAiInsight}
            >
              {loadingAi ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
              {loadingAi ? 'Analisando...' : 'Insight IA'}
            </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 lg:p-10">
          {aiInsight && (
            <div className="mb-8 p-4 bg-indigo-600/10 border border-indigo-500/30 rounded-xl flex gap-3 animate-in zoom-in-95 group relative">
              <Sparkles className="w-5 h-5 text-indigo-400 mt-1 shrink-0" />
              <div className="flex-1">
                <p className="text-sm text-indigo-100 pr-8 whitespace-pre-wrap">{aiInsight}</p>
              </div>
              <button 
                onClick={() => setAiInsight(null)} 
                className="absolute top-4 right-4 text-indigo-400/50 hover:text-indigo-400 transition-colors"
                title="Fechar insight"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
          )}
          {activePhase === 'dashboard' ? <Dashboard /> : <PhaseView phase={activePhase as CTIPhase} />}
        </div>
      </main>
    </div>
  );
}

export type CTIPhase = 'planning' | 'collection' | 'analysis' | 'dissemination' | 'feedback' | 'metrics';

export interface StatusHistory {
  status: string;
  date: string;
  action: 'Created' | 'Status Changed' | 'Edited';
}

export interface PIR {
  id: string;
  title: string;
  description: string;
  priority: 'High' | 'Medium' | 'Low';
  status: 'Active' | 'Draft' | 'Archived';
  history?: StatusHistory[];
}

export interface IntelligenceSource {
  id: string;
  name: string;
  type: 'Internal' | 'OSINT' | 'Commercial' | 'DarkWeb';
  confidence: number; // 0-100 (OpenCTI standard)
  integrationDate: string;
  reliability: 'A' | 'B' | 'C' | 'D' | 'E' | 'F'; // Admiralty Scale
}

export interface MetricRecord {
  id: string;
  pirId: string;
  hasIncident: boolean;
  incidentDate?: string;
  discoveryDate: string;
  disseminationDate: string;
  wasPreviouslyReported: boolean;
  incidentPrevented: boolean;
  impactScale: 'Low' | 'Medium' | 'High' | 'Critical';
}

export interface DisseminationLog {
  id: string;
  date: string;
  type: 'Strategic' | 'Operational' | 'Tactical';
  reportName: string;
  observations?: string;
}

export interface Report {
  id: string;
  title: string;
  type: 'Strategic' | 'Operational' | 'Tactical';
  content: string;
  date: string;
}

export interface KPI {
  name: string;
  value: number;
  unit: string;
}

export interface ClientData {
  id: string;
  name: string;
  sector: string;
  phases: {
    planning: { pirs: PIR[]; stakeholders: string[] };
    collection: { sources: IntelligenceSource[] };
    analysis: { reports: Report[]; ttps: string[] };
    dissemination: { 
      integrations: string[]; 
      alertsCount: number;
      logs: DisseminationLog[];
    };
    feedback: { kpis: KPI[]; improvements: string[] };
  };
  metrics: MetricRecord[];
}

export interface AppState {
  clients: ClientData[];
  activeClientId: string | null;
}

