      feedback: { kpis: [], improvements: [] }
    },
    metrics: [
      { id: 'm1', pirId: 'p1', hasIncident: true, incidentDate: '2024-05-10T08:00', discoveryDate: '2024-05-08T10:00', disseminationDate: '2024-05-09T14:00', wasPreviouslyReported: true, incidentPrevented: true, impactScale: 'High' }
    ]
  }
];

const PHASE_ORDER: CTIPhase[] = ['planning', 'collection', 'analysis', 'dissemination', 'feedback'];

const COLOR_VARIANTS: Record<string, { bg: string; text: string; border: string; dot: string }> = {
  blue: { bg: 'bg-blue-500/10', text: 'text-blue-400', border: 'border-blue-500/20', dot: 'bg-blue-500' },
  emerald: { bg: 'bg-emerald-500/10', text: 'text-emerald-400', border: 'border-emerald-500/20', dot: 'bg-emerald-500' },
  amber: { bg: 'bg-amber-500/10', text: 'text-amber-400', border: 'border-amber-500/20', dot: 'bg-amber-500' },
  purple: { bg: 'bg-purple-500/10', text: 'text-purple-400', border: 'border-purple-500/20', dot: 'bg-purple-500' },
  rose: { bg: 'bg-rose-500/10', text: 'text-rose-400', border: 'border-rose-500/20', dot: 'bg-rose-500' },
  indigo: { bg: 'bg-indigo-500/10', text: 'text-indigo-400', border: 'border-indigo-500/20', dot: 'bg-indigo-500' },
};

export default function App() {
  const [clients, setClients] = useState<ClientData[]>(INITIAL_CLIENTS);
  const [activeClientId, setActiveClientId] = useState<string | null>(INITIAL_CLIENTS[0].id);
  const [activePhase, setActivePhase] = useState<CTIPhase | 'dashboard' | 'cases'>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Modals
  const [isMetricModalOpen, setIsMetricModalOpen] = useState(false);
  const [isDisseminationModalOpen, setIsDisseminationModalOpen] = useState(false);
  const [editingMetric, setEditingMetric] = useState<MetricRecord | null>(null);

  const activeClient = useMemo(() => 
    clients.find(c => c.id === activeClientId) || null
  , [clients, activeClientId]);

  const performanceStats = useMemo(() => {
    if (!activeClient || activeClient.metrics.length === 0) return null;
    const diffHours = (d1: string, d2: string) => Math.max(0, (new Date(d1).getTime() - new Date(d2).getTime()) / (1000 * 60 * 60));
    const mttd = activeClient.metrics.reduce((acc, m) => acc + diffHours(m.discoveryDate, m.incidentDate || m.discoveryDate), 0) / activeClient.metrics.length;
    const mttdis = activeClient.metrics.reduce((acc, m) => acc + diffHours(m.disseminationDate, m.discoveryDate), 0) / activeClient.metrics.length;
    const reportedCount = activeClient.metrics.filter(m => m.wasPreviouslyReported).length;
    const preventedCount = activeClient.metrics.filter(m => m.incidentPrevented).length;
    return {
      mttd: mttd.toFixed(1),
      mttdis: mttdis.toFixed(1),
      accuracy: ((reportedCount / activeClient.metrics.length) * 100).toFixed(0),
      prevention: ((preventedCount / activeClient.metrics.length) * 100).toFixed(0)
    };
  }, [activeClient]);

  const handleAiInsight = async () => {
    if (!activeClient) return;
    setLoadingAi(true);
    setAiInsight(null);
    try {
      const context = `Cliente: ${activeClient.name}. Fase: ${activePhase}. Métricas: ${JSON.stringify(performanceStats)}`;
      const result = await generateCTIInsight("Analise os dados e sugira melhorias táticas.", context);
      setAiInsight(result);
    } catch (e) { console.error(e); } finally { setLoadingAi(false); }
  };

  const handleAddOrEditMetric = (metric: Omit<MetricRecord, 'id'>) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => c.id === activeClientId ? {
      ...c,
      metrics: editingMetric 
        ? c.metrics.map(m => m.id === editingMetric.id ? { ...metric, id: editingMetric.id } : m)
        : [...c.metrics, { ...metric, id: Math.random().toString(36).substr(2, 9) }]
    } : c));
    setIsMetricModalOpen(false);
    setEditingMetric(null);
  };

  const handleDeleteMetric = (id: string) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => c.id === activeClientId ? {
      ...c,
      metrics: c.metrics.filter(m => m.id !== id)
    } : c));
  };

  const handleAddDissemination = (log: Omit<DisseminationLog, 'id'>) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => c.id === activeClientId ? {
      ...c,
      phases: {
        ...c.phases,
        dissemination: {
          ...c.phases.dissemination,
          logs: [...c.phases.dissemination.logs, { ...log, id: Math.random().toString(36).substr(2, 9) }]
        }
      }
    } : c));
    setIsDisseminationModalOpen(false);
  };

  const MetricEntryModal = () => {
    const [form, setForm] = useState<Omit<MetricRecord, 'id'>>(editingMetric ? { ...editingMetric } : {
      pirId: activeClient?.phases.planning.pirs[0]?.id || '',
      hasIncident: false,
      incidentDate: '',
      discoveryDate: '',
      disseminationDate: '',
      wasPreviouslyReported: false,
      incidentPrevented: false,
      impactScale: 'Medium'
    });

    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
        <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-sm" onClick={() => { setIsMetricModalOpen(false); setEditingMetric(null); }} />
        <div className="relative bg-slate-900 border border-slate-800 w-full max-w-xl rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95">
          <div className="px-6 py-4 border-b border-slate-800 flex justify-between items-center bg-slate-800/20">
            <h3 className="font-bold text-lg flex items-center gap-2">
              <BarChart className="w-5 h-5 text-indigo-400" /> {editingMetric ? 'Editar Registro' : 'Novo Registro de Caso'}
            </h3>
            <button onClick={() => { setIsMetricModalOpen(false); setEditingMetric(null); }}><X className="w-6 h-6 text-slate-500" /></button>
          </div>
          <div className="p-6 space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">PIR Relacionado</label>
                <select value={form.pirId} onChange={e => setForm({...form, pirId: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white">
                  {activeClient?.phases.planning.pirs.map(p => <option key={p.id} value={p.id}>{p.title}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Impacto Estimado</label>
                <select value={form.impactScale} onChange={e => setForm({...form, impactScale: e.target.value as any})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white">
                  <option value="Low">Baixo</option><option value="Medium">Médio</option><option value="High">Alto</option><option value="Critical">Crítico</option>
                </select>
              </div>
            </div>

            <div className="flex items-center gap-2 py-2">
               <input type="checkbox" id="hasIncident" checked={form.hasIncident} onChange={e => setForm({...form, hasIncident: e.target.checked})} className="w-4 h-4 rounded bg-slate-950 border-slate-800 text-indigo-600" />
               <label htmlFor="hasIncident" className="text-sm text-slate-300 font-medium">Houve incidente associado?</label>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {form.hasIncident && (
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Data do Incidente</label>
                  <input type="datetime-local" value={form.incidentDate} onChange={e => setForm({...form, incidentDate: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white" />
                </div>
              )}
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Data da Descoberta</label>
                <input type="datetime-local" value={form.discoveryDate} onChange={e => setForm({...form, discoveryDate: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Data da Disseminação</label>
                <input type="datetime-local" value={form.disseminationDate} onChange={e => setForm({...form, disseminationDate: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white" />
              </div>
            </div>

            <div className="flex gap-6 pt-2">
              <label className="flex items-center gap-2 cursor-pointer">
                <input type="checkbox" checked={form.wasPreviouslyReported} onChange={e => setForm({...form, wasPreviouslyReported: e.target.checked})} className="w-4 h-4 rounded bg-slate-950 border-slate-800 text-indigo-600" />
                <span className="text-sm text-slate-300">Constava em relatórios?</span>
              </label>
              <label className="flex items-center gap-2 cursor-pointer">
                <input type="checkbox" checked={form.incidentPrevented} onChange={e => setForm({...form, incidentPrevented: e.target.checked})} className="w-4 h-4 rounded bg-slate-950 border-slate-800 text-emerald-600" />
                <span className="text-sm text-slate-300">Impedido/Mitigado?</span>
              </label>
            </div>
          </div>
          <div className="px-6 py-4 bg-slate-800/20 border-t border-slate-800 flex justify-end gap-3">
            <button onClick={() => { setIsMetricModalOpen(false); setEditingMetric(null); }} className="text-sm text-slate-400 font-medium">Cancelar</button>
            <button onClick={() => handleAddOrEditMetric(form)} className="bg-indigo-600 hover:bg-indigo-500 text-white px-6 py-2 rounded-xl text-sm font-bold transition-all shadow-lg shadow-indigo-900/20">
              {editingMetric ? 'Salvar Alterações' : 'Salvar Registro'}
            </button>
          </div>
        </div>
      </div>
    );
  };

  const DisseminationModal = () => {
    const [form, setForm] = useState<Omit<DisseminationLog, 'id'>>({
      date: new Date().toISOString().split('T')[0],
      type: 'Operational',
      reportName: '',
      observations: ''
    });

    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
        <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-sm" onClick={() => setIsDisseminationModalOpen(false)} />
        <div className="relative bg-slate-900 border border-slate-800 w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95">
          <div className="px-6 py-4 border-b border-slate-800 flex justify-between items-center bg-slate-800/20">
            <h3 className="font-bold text-lg">Novo Registro de Disseminação</h3>
            <button onClick={() => setIsDisseminationModalOpen(false)}><X className="w-6 h-6 text-slate-500" /></button>
          </div>
          <div className="p-6 space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Data de Disseminação</label>
                <input type="date" value={form.date} onChange={e => setForm({...form, date: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Tipo de Inteligência</label>
                <select value={form.type} onChange={e => setForm({...form, type: e.target.value as any})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white">
                  <option value="Strategic">Estratégica</option><option value="Operational">Operacional</option><option value="Tactical">Tática</option>
                </select>
              </div>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Relatório / Anexo (URL ou Nome)</label>
              <div className="relative">
                <Paperclip className="w-4 h-4 absolute left-3 top-2.5 text-slate-500" />
                <input type="text" placeholder="ex: Relatorio_Tatico_V1.pdf" value={form.reportName} onChange={e => setForm({...form, reportName: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg py-2 pl-10 pr-4 text-sm text-white" />
              </div>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Observações (Opcional)</label>
              <textarea rows={3} value={form.observations} onChange={e => setForm({...form, observations: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white resize-none" />
            </div>
          </div>
          <div className="px-6 py-4 bg-slate-800/20 border-t border-slate-800 flex justify-end gap-3">
            <button onClick={() => setIsDisseminationModalOpen(false)} className="text-sm text-slate-400 font-medium">Cancelar</button>
            <button onClick={() => handleAddDissemination(form)} className="bg-purple-600 hover:bg-purple-500 text-white px-6 py-2 rounded-xl text-sm font-bold shadow-lg shadow-purple-900/20">Registrar</button>
          </div>
        </div>
      </div>
    );
  };

  const CasesManager = () => {
    if (!activeClient) return null;
    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-bold text-white mb-1">Gestão de Casos</h1>
            <p className="text-slate-400">CRUD de incidentes e métricas de inteligência.</p>
          </div>
          <button onClick={() => setIsMetricModalOpen(true)} className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 px-4 py-2 rounded-xl font-bold transition-all shadow-lg shadow-indigo-900/20">
            <Plus className="w-4 h-4" /> Novo Caso
          </button>
        </header>

        <div className="bg-slate-900/50 border border-slate-800 rounded-2xl overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead>
                <tr className="text-slate-500 border-b border-slate-800 uppercase tracking-wider text-[11px]">
                  <th className="py-4 px-6">PIR</th>
                  <th className="py-4 px-6">Incidente</th>
                  <th className="py-4 px-6">Status Precisão</th>
                  <th className="py-4 px-6">Mitigado?</th>
                  <th className="py-4 px-6 text-right">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/50">
                {activeClient.metrics.map(m => (
                  <tr key={m.id} className="hover:bg-slate-800/30 transition-colors">
                    <td className="py-4 px-6">
                       <span className="text-slate-200 font-medium">{activeClient.phases.planning.pirs.find(p => p.id === m.pirId)?.title || m.pirId}</span>
                    </td>
                    <td className="py-4 px-6">
                       {m.hasIncident ? <span className="text-rose-400 flex items-center gap-2"><AlertTriangle className="w-3.5 h-3.5" /> {new Date(m.incidentDate!).toLocaleDateString()}</span> : <span className="text-slate-500">Nenhum</span>}
                    </td>
                    <td className="py-4 px-6">
                       {m.wasPreviouslyReported ? <span className="bg-emerald-500/10 text-emerald-400 px-2 py-0.5 rounded text-[10px] font-bold">REPORTADO</span> : <span className="bg-rose-500/10 text-rose-400 px-2 py-0.5 rounded text-[10px] font-bold">NÃO DETECTADO</span>}
                    </td>
                    <td className="py-4 px-6">
                       {m.incidentPrevented ? <CheckCircle className="w-5 h-5 text-emerald-500" /> : <X className="w-5 h-5 text-rose-500" />}
                    </td>
                    <td className="py-4 px-6 text-right space-x-2">
                       <button onClick={() => { setEditingMetric(m); setIsMetricModalOpen(true); }} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400 hover:text-white transition-colors"><Edit2 className="w-4 h-4" /></button>
                       <button onClick={() => handleDeleteMetric(m.id)} className="p-2 hover:bg-rose-500/10 rounded-lg text-slate-500 hover:text-rose-400 transition-colors"><Trash className="w-4 h-4" /></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {activeClient.metrics.length === 0 && (
              <div className="py-20 text-center text-slate-500"><Activity className="w-12 h-12 mx-auto mb-4 opacity-20" /><p>Nenhum caso registrado ainda.</p></div>
            )}
          </div>
        </div>
      </div>
    );
  };

  const PhaseView = ({ phase }: { phase: CTIPhase }) => {
    const config = PHASE_CONFIG[phase];
    if (!activeClient) return null;
    const phaseIndex = PHASE_ORDER.indexOf(phase);
    const prevPhase = phaseIndex > 0 ? PHASE_ORDER[phaseIndex - 1] : null;
    const nextPhase = phaseIndex < PHASE_ORDER.length - 1 ? PHASE_ORDER[phaseIndex + 1] : null;

    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500 pb-20">
        <header className="mb-8 flex justify-between items-start">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <div className={`p-2 bg-${config.color}-500/20 text-${config.color}-400 rounded-lg`}>{config.icon}</div>
              <h1 className="text-3xl font-bold text-white">{config.title}</h1>
            </div>
            <p className="text-slate-400">Gestão de {config.title.toLowerCase()}.</p>
          </div>
          <div className="flex items-center gap-2 bg-slate-900/50 p-1 rounded-xl border border-slate-800">
             <button disabled={!prevPhase} onClick={() => setActivePhase(prevPhase!)} className="p-2 text-slate-500 hover:text-white disabled:opacity-20 transition-all rounded-lg"><ChevronLeft className="w-5 h-5" /></button>
             <button disabled={!nextPhase} onClick={() => setActivePhase(nextPhase!)} className="p-2 text-slate-500 hover:text-white disabled:opacity-20 transition-all rounded-lg"><ChevronRight className="w-5 h-5" /></button>
          </div>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="md:col-span-3 space-y-6">
            <div className="bg-slate-900/50 border border-slate-800 rounded-2xl overflow-hidden">
              <div className="px-6 py-4 border-b border-slate-800 flex justify-between items-center bg-slate-800/20">
                <h3 className="font-semibold">{phase === 'dissemination' ? 'Logs de Disseminação' : 'Registros da Fase'}</h3>
                {phase === 'dissemination' && (
                  <button onClick={() => setIsDisseminationModalOpen(true)} className="text-purple-400 hover:text-purple-300 text-sm flex items-center gap-1 font-medium bg-purple-400/10 px-3 py-1.5 rounded-lg border border-purple-400/20 transition-all">
                    <Plus className="w-4 h-4" /> Novo Registro
                  </button>
                )}
              </div>
              <div className="p-6">
                {phase === 'dissemination' ? (
                  <div className="space-y-4">
                    {activeClient.phases.dissemination.logs.map(log => (
                      <div key={log.id} className="p-4 bg-slate-800/50 rounded-xl border border-slate-700 hover:border-purple-500/50 transition-all group">
                         <div className="flex justify-between items-start mb-3">
                            <div>
                               <div className="flex items-center gap-2 mb-1">
                                  <Calendar className="w-3.5 h-3.5 text-slate-500" />
                                  <span className="text-xs text-slate-400">{new Date(log.date).toLocaleDateString()}</span>
                                  <span className={`text-[10px] px-2 py-0.5 rounded font-bold border ${
                                    log.type === 'Strategic' ? 'bg-indigo-500/20 text-indigo-400 border-indigo-500/30' :
                                    log.type === 'Operational' ? 'bg-amber-500/20 text-amber-400 border-amber-500/30' :
                                    'bg-rose-500/20 text-rose-400 border-rose-500/30'
                                  }`}>{log.type}</span>
                               </div>
                               <h4 className="font-bold text-slate-200 flex items-center gap-2">
                                  <FileText className="w-4 h-4 text-slate-500" /> {log.reportName}
                               </h4>
                            </div>
                         </div>
                         {log.observations && <p className="text-sm text-slate-400 italic">"{log.observations}"</p>}
                      </div>
                    ))}
                    {activeClient.phases.dissemination.logs.length === 0 && <div className="py-10 text-center text-slate-500 opacity-50"><Share2 className="w-10 h-10 mx-auto mb-2" /><p>Nenhuma disseminação registrada.</p></div>}
                  </div>
                ) : phase === 'collection' ? (
                  <table className="w-full text-left text-sm">
                    <thead><tr className="text-slate-500 border-b border-slate-800 uppercase tracking-wider text-[11px]"><th className="pb-4 px-2">Fonte</th><th className="pb-4 px-2">Confiança</th><th className="pb-4 px-2 text-right">Integração</th></tr></thead>
                    <tbody>
                      {activeClient.phases.collection.sources.map(s => (
                        <tr key={s.id} className="border-b border-slate-800/50 hover:bg-slate-800/30 transition-colors"><td className="py-4 px-2 font-bold text-slate-100">{s.name}</td><td className="py-4 px-2 text-indigo-400">{s.confidence}%</td><td className="py-4 px-2 text-right text-slate-500">{s.integrationDate}</td></tr>
                      ))}
                    </tbody>
                  </table>
                ) : <div className="py-10 text-center text-slate-600"><Database className="w-10 h-10 mx-auto mb-2 opacity-20" /><p>Dados em processamento...</p></div>}
              </div>
            </div>
          </div>
          <div className="bg-slate-900/80 border border-slate-800 rounded-2xl p-6 h-fit shadow-xl">
             <h4 className="text-xs font-bold text-slate-500 uppercase mb-4 tracking-widest border-b border-slate-800 pb-2">Contexto</h4>
             <div className="space-y-4">
               <div><h5 className="text-indigo-400 text-[10px] font-bold uppercase mb-2">Entradas</h5><ul className="space-y-1">{config.inputs.map(i => <li key={i} className="text-xs text-slate-400">• {i}</li>)}</ul></div>
               <div><h5 className="text-emerald-400 text-[10px] font-bold uppercase mb-2">Saídas</h5><ul className="space-y-1">{config.outputs.map(o => <li key={o} className="text-xs text-slate-400">• {o}</li>)}</ul></div>
             </div>
          </div>
        </div>
      </div>
    );
  };

  const NavItem = ({ active, onClick, icon, label, color = 'indigo' }: any) => {
    const variant = COLOR_VARIANTS[color] || COLOR_VARIANTS.indigo;
    return (
      <button onClick={onClick} className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all group ${active ? `${variant.bg} ${variant.text} border ${variant.border}` : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'}`}>
        <div className={`${active ? variant.text : 'text-slate-500 group-hover:text-slate-300'}`}>{icon}</div>
        <span className="text-sm font-medium">{label}</span>
      </button>
    );
  }

  const StatCard = ({ title, value, color }: any) => {
    const variant = COLOR_VARIANTS[color] || COLOR_VARIANTS.indigo;
    return (
      <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl hover:border-slate-700 transition-colors shadow-sm">
        <p className="text-xs font-bold text-slate-500 uppercase mb-2 tracking-widest">{title}</p>
        <span className="text-3xl font-bold text-white">{value}</span>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-950">
      {isMetricModalOpen && <MetricEntryModal />}
      {isDisseminationModalOpen && <DisseminationModal />}

      <aside className={`bg-slate-900 border-r border-slate-800 transition-all duration-300 flex flex-col ${isSidebarOpen ? 'w-64' : 'w-0 overflow-hidden'}`}>
        <div className="p-6 flex items-center gap-3"><div className="bg-indigo-600 p-2 rounded-xl"><Shield className="w-6 h-6 text-white" /></div><span className="font-bold text-xl text-white">CTI Sentinel</span></div>
        <div className="px-4 py-6 flex-1 space-y-6 overflow-y-auto">
          <div><label className="text-[10px] font-bold text-slate-500 uppercase px-2 mb-3 block">Cliente</label>
            <div className="space-y-1">{clients.map(c => <button key={c.id} onClick={() => setActiveClientId(c.id)} className={`w-full text-left px-3 py-2 rounded-lg text-sm truncate ${activeClientId === c.id ? 'bg-indigo-500/10 text-indigo-400 border border-indigo-500/20' : 'text-slate-400 hover:bg-slate-800'}`}>{c.name}</button>)}</div>
          </div>
          <nav className="space-y-6">
            <div><label className="text-[10px] font-bold text-slate-500 uppercase px-2 mb-3 block">Menu</label>
              <NavItem active={activePhase === 'dashboard'} onClick={() => setActivePhase('dashboard')} icon={<LayoutDashboard className="w-4 h-4" />} label="Dashboard" />
              <NavItem active={activePhase === 'cases'} onClick={() => setActivePhase('cases')} icon={<Activity className="w-4 h-4" />} label="Gestão de Casos" color="rose" />
            </div>
            <div><label className="text-[10px] font-bold text-slate-500 uppercase px-2 mb-3 block">Ciclo de Vida</label>
              {(Object.keys(PHASE_CONFIG) as CTIPhase[]).map(p => <NavItem key={p} active={activePhase === p} onClick={() => setActivePhase(p)} icon={PHASE_CONFIG[p].icon} label={PHASE_CONFIG[p].title.split(' ')[0]} color={PHASE_CONFIG[p].color} />)}
            </div>
          </nav>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0">
        <header className="h-16 border-b border-slate-800 px-6 flex items-center justify-between bg-slate-900/30 backdrop-blur-md sticky top-0 z-10">
          <div className="flex items-center gap-4">
            <button onClick={toggleSidebar} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors">{isSidebarOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}</button>
            <div className="flex items-center gap-2 text-sm"><span className="text-slate-500">Programa</span><ChevronRight className="w-3 h-3 text-slate-700" /><span className="text-slate-200 font-medium">{activeClient?.name}</span></div>
          </div>
          <button disabled={loadingAi} className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 px-4 py-1.5 rounded-full text-sm font-medium disabled:opacity-50" onClick={handleAiInsight}>
            {loadingAi ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />} Insight IA
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-6 lg:p-10">
          {aiInsight && (
            <div className="mb-8 p-4 bg-indigo-600/10 border border-indigo-500/30 rounded-xl flex gap-3 animate-in zoom-in-95 relative group">
              <Sparkles className="w-5 h-5 text-indigo-400 mt-1 shrink-0" />
              <div className="flex-1"><p className="text-sm text-indigo-100 whitespace-pre-wrap">{aiInsight}</p></div>
              <button onClick={() => setAiInsight(null)} className="absolute top-4 right-4 text-slate-600 hover:text-white"><X className="w-4 h-4" /></button>
            </div>
          )}
          {activePhase === 'dashboard' ? <Dashboard /> : activePhase === 'cases' ? <CasesManager /> : <PhaseView phase={activePhase as CTIPhase} />}
        </div>
      </main>
    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
