        ], 
        stakeholders: ['CISO', 'Fraud Team'] 
      },
      collection: { 
        sources: [
          { id: 's1', name: 'AbuseIPDB', type: 'OSINT', confidence: 85, reliability: 'A', integrationDate: '2024-01-15' },
          { id: 's2', name: 'Flashpoint', type: 'Commercial', confidence: 95, reliability: 'B', integrationDate: '2024-02-10' }
        ]
      },
