  Activity,
  Calendar,
  AlertTriangle,
  FileText,
  Paperclip,
  Trash,
  Share2,
  Link as LinkIcon,
  BookOpen
} from 'lucide-react';
import { ClientData, CTIPhase, PIR, IntelligenceSource, Report, StatusHistory, MetricRecord, DisseminationLog } from './types';
import { PHASE_CONFIG } from './constants';
