                  </div>
                )}

                {/* DISSEMINATION PHASE CONTENT */}
                {phase === 'dissemination' && (
                  <div className="space-y-4">
                    {activeClient.phases.dissemination.logs.map(log => (
                      <div key={log.id} className="p-4 bg-slate-800/50 rounded-xl border border-slate-700 hover:border-purple-500/50 transition-all group">
