                  </div>
                )}

                {/* FEEDBACK PHASE PLACEHOLDER */}
                {phase === 'feedback' && <div className="py-10 text-center text-slate-600"><Database className="w-10 h-10 mx-auto mb-2 opacity-20" /><p>Módulo em implementação para fase de {config.title}...</p></div>}
              </div>
            </div>
          </div>
          <div className="bg-slate-900/80 border border-slate-800 rounded-2xl p-6 h-fit shadow-xl">
             <h4 className="text-xs font-bold text-slate-500 uppercase mb-4 tracking-widest border-b border-slate-800 pb-2">Contexto</h4>
