               <div><h5 className="text-indigo-400 text-[10px] font-bold uppercase mb-2">Entradas</h5><ul className="space-y-1">{config.inputs.map(i => <li key={i} className="text-xs text-slate-400">• {i}</li>)}</ul></div>
