             </div>
          </div>
        </div>
      </div>
    );
  };

  const NavItem = ({ active, onClick, icon, label, color = 'indigo' }: any) => {
    const variant = COLOR_VARIANTS[color] || COLOR_VARIANTS.indigo;
    return (
      <button onClick={onClick} className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all group ${active ? `${variant.bg} ${variant.text} border ${variant.border}` : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'}`}>
        <div className={`${active ? variant.text : 'text-slate-500 group-hover:text-slate-300'}`}>{icon}</div>
        <span className="text-sm font-medium">{label}</span>
      </button>
    );
  }

  const StatCard = ({ title, value, color }: any) => {
    const variant = COLOR_VARIANTS[color] || COLOR_VARIANTS.indigo;
    return (
      <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl hover:border-slate-700 transition-colors shadow-sm">
        <p className="text-xs font-bold text-slate-500 uppercase mb-2 tracking-widest">{title}</p>
        <span className="text-3xl font-bold text-white">{value}</span>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-950">
      {isMetricModalOpen && <MetricEntryModal />}
      {isDisseminationModalOpen && <DisseminationModal />}
      {isPirModalOpen && <PirModal />}
      {isSourceModalOpen && <SourceModal />}
      {isAnalysisModalOpen && <AnalysisModal />}

      <aside className={`bg-slate-900 border-r border-slate-800 transition-all duration-300 flex flex-col ${isSidebarOpen ? 'w-64' : 'w-0 overflow-hidden'}`}>
        <div className="p-6 flex items-center gap-3"><div className="bg-indigo-600 p-2 rounded-xl"><Shield className="w-6 h-6 text-white" /></div><span className="font-bold text-xl text-white">CTI Sentinel</span></div>
        <div className="px-4 py-6 flex-1 space-y-6 overflow-y-auto">
          <div><label className="text-[10px] font-bold text-slate-500 uppercase px-2 mb-3 block">Cliente</label>
            <div className="space-y-1">{clients.map(c => <button key={c.id} onClick={() => setActiveClientId(c.id)} className={`w-full text-left px-3 py-2 rounded-lg text-sm truncate ${activeClientId === c.id ? 'bg-indigo-500/10 text-indigo-400 border border-indigo-500/20' : 'text-slate-400 hover:bg-slate-800'}`}>{c.name}</button>)}</div>
          </div>
          <nav className="space-y-6">
            <div><label className="text-[10px] font-bold text-slate-500 uppercase px-2 mb-3 block">Menu</label>
              <NavItem active={activePhase === 'dashboard'} onClick={() => setActivePhase('dashboard')} icon={<LayoutDashboard className="w-4 h-4" />} label="Dashboard" />
              <NavItem active={activePhase === 'cases'} onClick={() => setActivePhase('cases')} icon={<Activity className="w-4 h-4" />} label="Gestão de Casos" color="rose" />
            </div>
            <div><label className="text-[10px] font-bold text-slate-500 uppercase px-2 mb-3 block">Ciclo de Vida</label>
              {(Object.keys(PHASE_CONFIG) as CTIPhase[]).map(p => <NavItem key={p} active={activePhase === p} onClick={() => setActivePhase(p)} icon={PHASE_CONFIG[p].icon} label={PHASE_CONFIG[p].title.split(' ')[0]} color={PHASE_CONFIG[p].color} />)}
            </div>
          </nav>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0">
        <header className="h-16 border-b border-slate-800 px-6 flex items-center justify-between bg-slate-900/30 backdrop-blur-md sticky top-0 z-10">
          <div className="flex items-center gap-4">
            <button onClick={toggleSidebar} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors">{isSidebarOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}</button>
            <div className="flex items-center gap-2 text-sm"><span className="text-slate-500">Programa</span><ChevronRight className="w-3 h-3 text-slate-700" /><span className="text-slate-200 font-medium">{activeClient?.name}</span></div>
          </div>
          <button disabled={loadingAi} className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 px-4 py-1.5 rounded-full text-sm font-medium disabled:opacity-50" onClick={handleAiInsight}>
            {loadingAi ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />} Insight IA
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-6 lg:p-10">
          {aiInsight && (
            <div className="mb-8 p-4 bg-indigo-600/10 border border-indigo-500/30 rounded-xl flex gap-3 animate-in zoom-in-95 relative group">
              <Sparkles className="w-5 h-5 text-indigo-400 mt-1 shrink-0" />
              <div className="flex-1"><p className="text-sm text-indigo-100 whitespace-pre-wrap">{aiInsight}</p></div>
              <button onClick={() => setAiInsight(null)} className="absolute top-4 right-4 text-slate-600 hover:text-white"><X className="w-4 h-4" /></button>
            </div>
          )}
          {activePhase === 'dashboard' ? <Dashboard /> : activePhase === 'cases' ? <CasesManager /> : <PhaseView phase={activePhase as CTIPhase} />}
        </div>
      </main>
    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
