export default function App() {
  const [clients, setClients] = useState<ClientData[]>(INITIAL_CLIENTS);
  const [activeClientId, setActiveClientId] = useState<string | null>(INITIAL_CLIENTS[0].id);
  const [activePhase, setActivePhase] = useState<CTIPhase | 'dashboard' | 'cases'>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // UI States
  const [expandedPirId, setExpandedPirId] = useState<string | null>(null);

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  // Modals
  const [isMetricModalOpen, setIsMetricModalOpen] = useState(false);
  const [isDisseminationModalOpen, setIsDisseminationModalOpen] = useState(false);
  const [isPirModalOpen, setIsPirModalOpen] = useState(false);
  const [isSourceModalOpen, setIsSourceModalOpen] = useState(false);
  const [isAnalysisModalOpen, setIsAnalysisModalOpen] = useState(false);

  // Editing state
  const [editingMetric, setEditingMetric] = useState<MetricRecord | null>(null);
  const [editingPir, setEditingPir] = useState<PIR | null>(null);
  const [editingSource, setEditingSource] = useState<IntelligenceSource | null>(null);
  const [editingAnalysis, setEditingAnalysis] = useState<Report | null>(null);

  const [sourceModalPirId, setSourceModalPirId] = useState<string | null>(null);
  const [analysisModalPirId, setAnalysisModalPirId] = useState<string | null>(null);

  const activeClient = useMemo(() => 
    clients.find(c => c.id === activeClientId) || null
  , [clients, activeClientId]);

  const performanceStats = useMemo(() => {
    if (!activeClient || activeClient.metrics.length === 0) return null;
    const diffHours = (d1: string, d2: string) => Math.max(0, (new Date(d1).getTime() - new Date(d2).getTime()) / (1000 * 60 * 60));
    const mttd = activeClient.metrics.reduce((acc, m) => acc + diffHours(m.discoveryDate, m.incidentDate || m.discoveryDate), 0) / activeClient.metrics.length;
    const mttdis = activeClient.metrics.reduce((acc, m) => acc + diffHours(m.disseminationDate, m.discoveryDate), 0) / activeClient.metrics.length;
    const reportedCount = activeClient.metrics.filter(m => m.wasPreviouslyReported).length;
    const preventedCount = activeClient.metrics.filter(m => m.incidentPrevented).length;
    return {
      mttd: mttd.toFixed(1),
      mttdis: mttdis.toFixed(1),
      accuracy: ((reportedCount / activeClient.metrics.length) * 100).toFixed(0),
      prevention: ((preventedCount / activeClient.metrics.length) * 100).toFixed(0)
    };
  }, [activeClient]);

  const handleAiInsight = async () => {
    if (!activeClient) return;
    setLoadingAi(true);
    setAiInsight(null);
    try {
      const context = `Cliente: ${activeClient.name}. Fase: ${activePhase}. Métricas: ${JSON.stringify(performanceStats)}`;
      const result = await generateCTIInsight("Analise os dados e sugira melhorias táticas ou operacionais.", context);
      setAiInsight(result);
    } catch (e) { console.error(e); } finally { setLoadingAi(false); }
  };

  // --- PIR Management ---
  const handleAddOrEditPir = (pir: Omit<PIR, 'id'>) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => {
      if (c.id !== activeClientId) return c;

      let updatedPirs = [...c.phases.planning.pirs];
      const now = new Date().toISOString();

      if (editingPir) {
        updatedPirs = updatedPirs.map(p => {
          if (p.id !== editingPir.id) return p;

          const newHistory: StatusHistory[] = [...(p.history || [])];
          let action: StatusHistory['action'] = 'Edited';

          if (p.status !== pir.status) {
            action = 'Status Changed';
          }

          newHistory.push({
            status: pir.status,
            date: now,
            action: action
          });

          return { ...pir, id: editingPir.id, history: newHistory };
        });
      } else {
        const newPir: PIR = {
          ...pir,
          id: Math.random().toString(36).substr(2, 9),
          history: [{
            status: pir.status,
            date: now,
            action: 'Created'
          }]
        };
        updatedPirs.push(newPir);
      }

      return {
        ...c,
        phases: {
          ...c.phases,
          planning: {
            ...c.phases.planning,
            pirs: updatedPirs
          }
        }
      };
    }));
    setIsPirModalOpen(false);
    setEditingPir(null);
  };

  const handleArchivePir = (id: string) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => {
      if (c.id !== activeClientId) return c;
      return {
        ...c,
        phases: {
          ...c.phases,
          planning: {
            ...c.phases.planning,
            pirs: c.phases.planning.pirs.map(p => p.id === id ? {
              ...p,
              status: 'Archived',
              history: [...(p.history || []), { 
                status: 'Archived', 
                date: new Date().toISOString(), 
                action: 'Status Changed' 
              }]
            } : p)
          }
        }
      };
    }));
  };

  const handleRestorePir = (id: string) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => {
      if (c.id !== activeClientId) return c;
      return {
        ...c,
        phases: {
          ...c.phases,
          planning: {
            ...c.phases.planning,
            pirs: c.phases.planning.pirs.map(p => p.id === id ? {
              ...p,
              status: 'Active',
              history: [...(p.history || []), { 
                status: 'Active', 
                date: new Date().toISOString(), 
                action: 'Status Changed' 
              }]
            } : p)
          }
        }
      };
    }));
  };

  const handleDeletePir = (id: string) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => c.id === activeClientId ? {
      ...c,
      phases: {
        ...c.phases,
        planning: {
          ...c.phases.planning,
          pirs: c.phases.planning.pirs.filter(p => p.id !== id)
        },
        collection: {
          ...c.phases.collection,
          sources: c.phases.collection.sources.filter(s => s.pirId !== id)
        },
        analysis: {
          ...c.phases.analysis,
          reports: c.phases.analysis.reports.filter(r => r.pirId !== id)
        }
      }
    } : c));
    if (expandedPirId === id) setExpandedPirId(null);
  };

  // --- Source Management ---
  const handleAddOrEditSource = (source: Omit<IntelligenceSource, 'id'>) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => c.id === activeClientId ? {
      ...c,
      phases: {
        ...c.phases,
        collection: {
          ...c.phases.collection,
          sources: editingSource 
            ? c.phases.collection.sources.map(s => s.id === editingSource.id ? { ...source, id: editingSource.id } : s)
            : [...c.phases.collection.sources, { ...source, id: Math.random().toString(36).substr(2, 9) }]
        }
      }
    } : c));
    setIsSourceModalOpen(false);
    setEditingSource(null);
    setSourceModalPirId(null);
  };

  const handleDeleteSource = (id: string) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => c.id === activeClientId ? {
      ...c,
      phases: {
        ...c.phases,
        collection: {
          ...c.phases.collection,
          sources: c.phases.collection.sources.filter(s => s.id !== id)
        }
      }
    } : c));
  };

  // --- Analysis Management ---
  const handleAddOrEditAnalysis = (report: Omit<Report, 'id'>) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => c.id === activeClientId ? {
      ...c,
      phases: {
        ...c.phases,
        analysis: {
          ...c.phases.analysis,
          reports: editingAnalysis
            ? c.phases.analysis.reports.map(r => r.id === editingAnalysis.id ? { ...report, id: editingAnalysis.id } : r)
            : [...c.phases.analysis.reports, { ...report, id: Math.random().toString(36).substr(2, 9) }]
        }
      }
    } : c));
    setIsAnalysisModalOpen(false);
    setEditingAnalysis(null);
    setAnalysisModalPirId(null);
  };

  const handleDeleteAnalysis = (id: string) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => c.id === activeClientId ? {
      ...c,
      phases: {
        ...c.phases,
        analysis: {
          ...c.phases.analysis,
          reports: c.phases.analysis.reports.filter(r => r.id !== id)
        }
      }
    } : c));
  };

  // --- Metrics Management ---
  const handleAddOrEditMetric = (metric: Omit<MetricRecord, 'id'>) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => c.id === activeClientId ? {
      ...c,
      metrics: editingMetric 
        ? c.metrics.map(m => m.id === editingMetric.id ? { ...metric, id: editingMetric.id } : m)
        : [...c.metrics, { ...metric, id: Math.random().toString(36).substr(2, 9) }]
    } : c));
    setIsMetricModalOpen(false);
    setEditingMetric(null);
  };

  const handleDeleteMetric = (id: string) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => c.id === activeClientId ? {
      ...c,
      metrics: c.metrics.filter(m => m.id !== id)
    } : c));
  };

  // --- Dissemination Management ---
  const handleAddDissemination = (log: Omit<DisseminationLog, 'id'>) => {
    if (!activeClientId) return;
    setClients(prev => prev.map(c => c.id === activeClientId ? {
      ...c,
      phases: {
        ...c.phases,
        dissemination: {
          ...c.phases.dissemination,
          logs: [...c.phases.dissemination.logs, { ...log, id: Math.random().toString(36).substr(2, 9) }]
        }
      }
    } : c));
    setIsDisseminationModalOpen(false);
  };

  // --- Modals Components ---

  const PirModal = () => {
    const [form, setForm] = useState<Omit<PIR, 'id'>>(editingPir ? { ...editingPir } : {
      title: '',
      description: '',
      priority: 'Medium',
      status: 'Active',
      history: []
    });

    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
        <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-sm" onClick={() => { setIsPirModalOpen(false); setEditingPir(null); }} />
        <div className="relative bg-slate-900 border border-slate-800 w-full max-w-lg rounded-2xl shadow-2xl animate-in zoom-in-95">
          <div className="px-6 py-4 border-b border-slate-800 flex justify-between items-center bg-slate-800/20">
            <h3 className="font-bold text-lg">{editingPir ? 'Editar PIR' : 'Novo PIR'}</h3>
            <button onClick={() => { setIsPirModalOpen(false); setEditingPir(null); }}><X className="w-6 h-6 text-slate-500" /></button>
          </div>
          <div className="p-6 space-y-4">
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Título do Requisito</label>
              <input type="text" value={form.title} onChange={e => setForm({...form, title: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white focus:border-blue-500 transition-colors" placeholder="ex: Monitorar Fraudes Pix" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Descrição</label>
              <textarea rows={3} value={form.description} onChange={e => setForm({...form, description: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white resize-none focus:border-blue-500 transition-colors" placeholder="Qual a pergunta de inteligência a ser respondida?" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Prioridade</label>
                <select value={form.priority} onChange={e => setForm({...form, priority: e.target.value as any})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white">
                  <option value="High">Alta</option><option value="Medium">Média</option><option value="Low">Baixa</option>
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Status</label>
                <select value={form.status} onChange={e => setForm({...form, status: e.target.value as any})} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-sm text-white">
                  <option value="Active">Ativo</option><option value="Draft">Rascunho</option><option value="Archived">Arquivado</option>
                </select>
              </div>
            </div>
          </div>
          <div className="px-6 py-4 bg-slate-800/20 border-t border-slate-800 flex justify-end gap-3">
            <button onClick={() => { setIsPirModalOpen(false); setEditingPir(null); }} className="text-sm text-slate-400 font-medium">Cancelar</button>
            <button onClick={() => handleAddOrEditPir(form)} className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-xl text-sm font-bold shadow-lg shadow-blue-900/20 transition-all">Salvar</button>
          </div>
        </div>
      </div>
    );
  };

  const SourceModal = () => {
    const [form, setForm] = useState<Omit<IntelligenceSource, 'id'>>(editingSource ? { ...editingSource } : {
