                          <span className="text-slate-200 font-bold">{activeClient.phases.planning.pirs.find(p => p.id === m.pirId)?.title || m.pirId}</span>
                          <span className="text-[10px] text-slate-500 uppercase font-mono mt-0.5">ID: {m.id}</span>
                       </div>
                    </td>
                    <td className="py-4 px-6">
                       {m.hasIncident ? (
                         <div className="flex flex-col">
                            <span className="text-rose-400 flex items-center gap-2 font-medium"><AlertTriangle className="w-3.5 h-3.5" /> Incidente Real</span>
                            <span className="text-[10px] text-slate-500 mt-0.5">{new Date(m.incidentDate!).toLocaleDateString()}</span>
                         </div>
                       ) : (
                         <div className="flex flex-col">
                            <span className="text-amber-400 flex items-center gap-2 font-medium"><Info className="w-3.5 h-3.5" /> Detecção Potencial</span>
                            <span className="text-[10px] text-slate-500 mt-0.5">{new Date(m.discoveryDate).toLocaleDateString()}</span>
                         </div>
                       )}
                    </td>
                    <td className="py-4 px-6">
                       {m.wasPreviouslyReported ? (
                         <span className="bg-emerald-500/10 text-emerald-400 px-2 py-0.5 rounded text-[10px] font-bold border border-emerald-500/20">ANTECIPADO</span>
                       ) : (
                         <span className="bg-rose-500/10 text-rose-400 px-2 py-0.5 rounded text-[10px] font-bold border border-rose-500/20">NÃO MAPEADO</span>
                       )}
                    </td>
                    <td className="py-4 px-6">
                       <div className="flex items-center gap-2">
                          {!m.hasIncident ? (
                            <div className="flex items-center gap-1.5 text-amber-500 font-medium"><AlertCircle className="w-4 h-4" /> Potencial</div>
                          ) : m.incidentPrevented ? (
                            <div className="flex items-center gap-1.5 text-emerald-500 font-medium"><CheckCircle className="w-4 h-4" /> Mitigado</div>
                          ) : (
                            <div className="flex items-center gap-1.5 text-rose-500 font-medium"><X className="w-4 h-4" /> Consumado</div>
                          )}
                       </div>
                    </td>
                    <td className="py-4 px-6 text-right">
                       <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => { setEditingMetric(m); setIsMetricModalOpen(true); }} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400 hover:text-white transition-colors"><Edit2 className="w-4 h-4" /></button>
                          <button onClick={() => handleDeleteMetric(m.id)} className="p-2 hover:bg-rose-500/10 rounded-lg text-slate-500 hover:text-rose-400 transition-colors"><Trash className="w-4 h-4" /></button>
                       </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {activeClient.metrics.length === 0 && (
              <div className="py-24 text-center text-slate-600">
                <Activity className="w-16 h-16 mx-auto mb-4 opacity-10" />
                <p className="text-lg font-medium opacity-50">Nenhum caso registrado ainda.</p>
                <button onClick={() => setIsMetricModalOpen(true)} className="text-indigo-400 text-sm mt-2 hover:underline">Começar a registrar agora</button>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  };

  const Dashboard = () => {
    if (!activeClient) return null;

    const chartData = activeClient.metrics.map(m => {
      const diffHours = (d1: string, d2: string) => Math.max(0, (new Date(d1).getTime() - new Date(d2).getTime()) / (1000 * 60 * 60));
      return {
        date: new Date(m.discoveryDate).toLocaleDateString(),
        mttd: diffHours(m.discoveryDate, m.incidentDate || m.discoveryDate), // Data de Descoberta - Data do Incidente
        mttdis: diffHours(m.disseminationDate, m.discoveryDate), // Data de Disseminação - Data de Descoberta
      };
    });

    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-10">
        <header className="mb-8">
          <h1 className="text-3xl font-bold text-white mb-2 tracking-tight">Status do Programa CTI</h1>
          <p className="text-slate-400">Indicadores chave de desempenho e eficácia operacional.</p>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <StatCard title="MTTD Médio" value={`${performanceStats?.mttd || '0.0'}h`} color="blue" description="Detecção da Ameaça" />
          <StatCard title="MTTDis Médio" value={`${performanceStats?.mttdis || '0.0'}h`} color="purple" description="Disseminação Intel" />
          <StatCard title="Antecipação" value={`${performanceStats?.accuracy || '0'}%`} color="emerald" description="Casos já mapeados em PIRs" />
          <StatCard title="Mitigação" value={`${performanceStats?.prevention || '0'}%`} color="rose" description="Sucesso em prevenir danos" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl h-[350px] shadow-sm">
            <h3 className="text-xs font-bold text-slate-500 uppercase mb-6 flex items-center gap-2 tracking-widest">
              <Activity className="w-4 h-4 text-indigo-400" /> Histórico de Resposta (MTTD vs MTTDis)
            </h3>
            <ResponsiveContainer width="100%" height="80%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorMttd" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                <XAxis dataKey="date" stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} />
                <YAxis stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} />
                <Tooltip contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '8px', color: '#fff', fontSize: '12px' }} />
                <Area type="monotone" dataKey="mttd" stroke="#3b82f6" strokeWidth={2} fillOpacity={1} fill="url(#colorMttd)" name="MTTD (h)" />
                <Area type="monotone" dataKey="mttdis" stroke="#a855f7" strokeWidth={2} fillOpacity={0} fill="none" name="MTTDis (h)" />
                <Legend iconType="circle" />
              </AreaChart>
            </ResponsiveContainer>
          </div>

          <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl h-[350px] shadow-sm">
            <h3 className="text-xs font-bold text-slate-500 uppercase mb-6 flex items-center gap-2 tracking-widest">
              <BarChart className="w-4 h-4 text-emerald-400" /> Distribuição de Impacto de Casos
            </h3>
            <ResponsiveContainer width="100%" height="80%">
              <ReBarChart data={[
                { name: 'Baixo', count: activeClient.metrics.filter(m => m.impactScale === 'Low').length },
                { name: 'Médio', count: activeClient.metrics.filter(m => m.impactScale === 'Medium').length },
                { name: 'Alto', count: activeClient.metrics.filter(m => m.impactScale === 'High').length },
                { name: 'Crítico', count: activeClient.metrics.filter(m => m.impactScale === 'Critical').length },
              ]}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                <XAxis dataKey="name" stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} />
                <YAxis stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} />
                <Tooltip cursor={{fill: '#1e293b', opacity: 0.5}} contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '8px', color: '#fff', fontSize: '12px' }} />
                <Bar dataKey="count" name="Quantidade de Casos" radius={[4, 4, 0, 0]}>
                   { [0, 1, 2, 3].map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={['#94a3b8', '#fbbf24', '#f87171', '#7f1d1d'][index]} />
                   )) }
                </Bar>
              </ReBarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    );
  };

  const PhaseView = ({ phase }: { phase: CTIPhase }) => {
    const config = PHASE_CONFIG[phase];
    if (!activeClient) return null;
    const phaseIndex = PHASE_ORDER.indexOf(phase);
    const prevPhase = phaseIndex > 0 ? PHASE_ORDER[phaseIndex - 1] : null;
    const nextPhase = phaseIndex < PHASE_ORDER.length - 1 ? PHASE_ORDER[phaseIndex + 1] : null;

    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500 pb-24">
        <header className="mb-8 flex justify-between items-start">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <div className={`p-2 bg-${config.color}-500/20 text-${config.color}-400 rounded-lg shadow-lg shadow-${config.color}-500/10`}>{config.icon}</div>
              <h1 className="text-3xl font-bold text-white tracking-tight">{config.title}</h1>
            </div>
            <p className="text-slate-400">Controle e registros da fase de {config.title.toLowerCase()}.</p>
          </div>
          <div className="flex items-center gap-2 bg-slate-900/50 p-1 rounded-xl border border-slate-800 backdrop-blur-sm">
             <button disabled={!prevPhase} onClick={() => setActivePhase(prevPhase!)} className="p-2 text-slate-500 hover:text-white disabled:opacity-20 transition-all rounded-lg hover:bg-slate-800"><ChevronLeft className="w-5 h-5" /></button>
             <button disabled={!nextPhase} onClick={() => setActivePhase(nextPhase!)} className="p-2 text-slate-500 hover:text-white disabled:opacity-20 transition-all rounded-lg hover:bg-slate-800"><ChevronRight className="w-5 h-5" /></button>
          </div>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <div className="lg:col-span-3 space-y-8">
            <div className="bg-slate-900/50 border border-slate-800 rounded-2xl overflow-hidden shadow-xl">
              <div className="px-6 py-4 border-b border-slate-800 flex justify-between items-center bg-slate-800/20">
                <h3 className="font-bold text-slate-200">
                  {phase === 'dissemination' ? 'Registros de Disseminação' : 
                   phase === 'collection' ? 'Fontes de Inteligência por PIR' : 
                   phase === 'planning' ? 'Prioritários de Inteligência (PIRs)' : 
                   phase === 'analysis' ? 'Análises e Relatórios por PIR' : 'Registros da Fase'}
                </h3>
                {phase === 'dissemination' && (
                  <button onClick={() => { setIsDisseminationModalOpen(true); }} className="text-purple-400 hover:text-purple-300 text-sm flex items-center gap-1.5 font-bold bg-purple-400/10 px-4 py-2 rounded-xl border border-purple-400/20 transition-all hover:bg-purple-400/20">
                    <Plus className="w-4 h-4" /> Novo Registro
                  </button>
                )}
                {phase === 'planning' && (
                  <button onClick={() => { setEditingPir(null); setIsPirModalOpen(true); }} className="text-blue-400 hover:text-blue-300 text-sm flex items-center gap-1.5 font-bold bg-blue-400/10 px-4 py-2 rounded-xl border border-blue-400/20 transition-all hover:bg-blue-400/20">
                    <Plus className="w-4 h-4" /> Criar PIR
                  </button>
                )}
              </div>
              <div className="p-6">
                {/* PLANNING PHASE CONTENT */}
                {phase === 'planning' && (
                   <div className="grid grid-cols-1 gap-4">
                      {activeClient.phases.planning.pirs.map(pir => (
                        <div key={pir.id} className={`bg-slate-800/30 rounded-2xl border border-slate-800 hover:border-blue-500/40 transition-all group overflow-hidden ${expandedPirId === pir.id ? 'border-blue-500/50' : ''}`}>
                           <div className="p-5 flex justify-between items-start cursor-pointer" onClick={() => setExpandedPirId(expandedPirId === pir.id ? null : pir.id)}>
                              <div className="flex-1 pr-10">
                                 <div className="flex items-center gap-2 mb-1">
                                    <h4 className="font-bold text-slate-100 group-hover:text-blue-400 transition-colors leading-tight">{pir.title}</h4>
                                    <span className="text-[9px] font-mono text-slate-600 uppercase">ID: {pir.id}</span>
                                 </div>
                                 <p className="text-sm text-slate-400 line-clamp-1 leading-relaxed">{pir.description}</p>
                              </div>
                              <div className="flex items-center gap-4 shrink-0">
                                 <span className={`text-[10px] px-2 py-0.5 rounded font-bold border ${pir.priority === 'High' ? 'bg-rose-500/10 text-rose-400 border-rose-500/20' : 'bg-amber-500/10 text-amber-400 border-amber-500/20'}`}>{pir.priority}</span>
                                 <div className="text-slate-600">
                                    {expandedPirId === pir.id ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
                                 </div>
                              </div>
                           </div>

                           {/* ACTIONS SECTION */}
                           <div className="px-5 py-3 bg-slate-800/20 border-t border-slate-800 flex items-center gap-4">
                              <button onClick={(e) => { e.stopPropagation(); setEditingPir(pir); setIsPirModalOpen(true); }} className="text-[11px] font-bold text-slate-400 hover:text-white flex items-center gap-1.5 transition-colors"><Edit2 className="w-3.5 h-3.5" /> Editar</button>

                              {pir.status !== 'Archived' ? (
                                <button onClick={(e) => { e.stopPropagation(); handleArchivePir(pir.id); }} className="text-[11px] font-bold text-slate-400 hover:text-amber-400 flex items-center gap-1.5 transition-colors"><Archive className="w-3.5 h-3.5" /> Arquivar</button>
                              ) : (
                                <button onClick={(e) => { e.stopPropagation(); handleRestorePir(pir.id); }} className="text-[11px] font-bold text-emerald-500 hover:text-emerald-400 flex items-center gap-1.5 transition-colors"><RefreshCw className="w-3.5 h-3.5" /> Reativar</button>
                              )}

                              <button onClick={(e) => { e.stopPropagation(); handleDeletePir(pir.id); }} className="text-[11px] font-bold text-slate-400 hover:text-rose-400 flex items-center gap-1.5 transition-colors ml-auto"><Trash className="w-3.5 h-3.5" /> Deletar</button>
                           </div>

                           {/* EXPANDED CONTENT: STATUS HISTORY */}
                           {expandedPirId === pir.id && (
                             <div className="px-5 pb-6 pt-2 animate-in slide-in-from-top-2 duration-300">
                                <div className="border-t border-slate-800/50 pt-5 mt-2">
                                   <div className="flex items-center gap-2 mb-6">
                                      <History className="w-4 h-4 text-blue-400" />
                                      <h5 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Histórico de Ciclo de Vida</h5>
                                   </div>
                                   <div className="space-y-6 relative ml-3">
                                      <div className="absolute left-0 top-0 bottom-0 w-0.5 bg-slate-800"></div>
                                      {(pir.history || []).slice().reverse().map((h, idx) => (
                                        <div key={idx} className="relative pl-6">
                                           <div className={`absolute -left-[5px] top-1.5 w-2.5 h-2.5 rounded-full ${idx === 0 ? 'bg-blue-500 shadow-lg shadow-blue-500/50' : 'bg-slate-700'}`}></div>
                                           <div className="flex items-start justify-between">
                                              <div>
                                                 <span className={`text-[9px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded border mb-1.5 inline-block ${
                                                   h.action === 'Created' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' :
                                                   h.action === 'Status Changed' ? 'bg-blue-500/10 text-blue-400 border-blue-500/20' :
                                                   'bg-slate-800 text-slate-400 border-slate-700'
                                                 }`}>{h.action}</span>
                                                 <p className="text-xs text-slate-300 font-medium">Status definido para: <span className="text-slate-100 font-bold">{h.status}</span></p>
                                              </div>
                                              <div className="text-[10px] text-slate-600 font-mono">
                                                 {new Date(h.date).toLocaleString('pt-BR')}
                                              </div>
                                           </div>
                                        </div>
                                      ))}
                                      {(!pir.history || pir.history.length === 0) && (
                                        <p className="text-xs text-slate-600 italic pl-6">Nenhum histórico registrado para este requisito.</p>
                                      )}
                                   </div>
                                </div>
                             </div>
                           )}
                        </div>
                      ))}
                      {activeClient.phases.planning.pirs.length === 0 && (
                        <div className="py-20 text-center text-slate-600 italic border-2 border-dashed border-slate-800 rounded-2xl">
                          Nenhum PIR cadastrado. Inicie o ciclo definindo os Requisitos Prioritários.
                        </div>
                      )}
                   </div>
                )}

                {/* COLLECTION PHASE CONTENT */}
                {phase === 'collection' && (
                  <div className="space-y-12">
                    {activeClient.phases.planning.pirs.map(pir => (
                      <div key={pir.id} className="space-y-4">
                        <div className="flex justify-between items-center border-b border-slate-800 pb-2">
                          <h4 className="font-bold text-emerald-400 flex items-center gap-2"><LinkIcon className="w-4 h-4" /> {pir.title}</h4>
                          <button onClick={() => { setSourceModalPirId(pir.id); setEditingSource(null); setIsSourceModalOpen(true); }} className="text-[10px] font-bold uppercase tracking-wider bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 px-3 py-1.5 rounded-lg hover:bg-emerald-500/20 transition-all">+ Nova Fonte</button>
                        </div>
                        <div className="overflow-x-auto">
                          <table className="w-full text-left text-sm">
                            <thead>
                              <tr className="text-slate-600 uppercase text-[10px] tracking-widest font-bold">
                                <th className="pb-4 pr-4">Fonte / Ativo</th>
                                <th className="pb-4 pr-4">Tipo</th>
                                <th className="pb-4 pr-4">Confiança</th>
                                <th className="pb-4 pr-4 text-center">Rel.</th>
                                <th className="pb-4 text-right">Ações</th>
                              </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-800/30">
                              {activeClient.phases.collection.sources.filter(s => s.pirId === pir.id).map(source => (
                                <tr key={source.id} className="group hover:bg-slate-800/20 transition-colors">
                                  <td className="py-4 pr-4 font-bold text-slate-300">{source.name}</td>
                                  <td className="py-4 pr-4"><span className="text-[10px] text-slate-500 border border-slate-800 px-1.5 py-0.5 rounded">{source.type}</span></td>
                                  <td className="py-4 pr-4">
                                     <div className="flex items-center gap-3">
                                        <div className="flex-1 h-1.5 bg-slate-800 rounded-full min-w-[80px] overflow-hidden"><div className="h-full bg-emerald-500 transition-all duration-1000" style={{ width: `${source.confidence}%` }}></div></div>
                                        <span className="text-[10px] font-mono text-slate-500">{source.confidence}%</span>
                                     </div>
                                  </td>
                                  <td className="py-4 pr-4 text-center text-xs font-bold text-indigo-400">{source.reliability}</td>
                                  <td className="py-4 text-right">
                                     <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button onClick={() => { setEditingSource(source); setIsSourceModalOpen(true); }} className="p-1.5 hover:bg-slate-700 rounded text-slate-400 hover:text-white transition-all"><Edit2 className="w-3.5 h-3.5" /></button>
                                        <button onClick={() => handleDeleteSource(source.id)} className="p-1.5 hover:bg-rose-500/10 rounded text-slate-400 hover:text-rose-400 transition-all"><Trash className="w-3.5 h-3.5" /></button>
                                     </div>
                                  </td>
                                </tr>
                              ))}
                              {activeClient.phases.collection.sources.filter(s => s.pirId === pir.id).length === 0 && (
                                <tr><td colSpan={5} className="py-8 text-sm text-slate-600 italic text-center">Nenhuma fonte vinculada a este requisito de inteligência.</td></tr>
                              )}
                            </tbody>
                          </table>
                        </div>
                      </div>
                    ))}
                    {activeClient.phases.planning.pirs.length === 0 && (
                      <div className="py-20 text-center text-slate-600 italic border-2 border-dashed border-slate-800 rounded-2xl">
                        Inicie definindo os PIRs para poder mapear as fontes de coleta.
                      </div>
                    )}
                  </div>
                )}

                {/* ANALYSIS PHASE CONTENT */}
                {phase === 'analysis' && (
                  <div className="space-y-12">
                    {activeClient.phases.planning.pirs.map(pir => (
                      <div key={pir.id} className="space-y-4">
                        <div className="flex justify-between items-center border-b border-slate-800 pb-2">
                          <h4 className="font-bold text-amber-400 flex items-center gap-2"><BookOpen className="w-4 h-4" /> {pir.title}</h4>
                          <button onClick={() => { setAnalysisModalPirId(pir.id); setEditingAnalysis(null); setIsAnalysisModalOpen(true); }} className="text-[10px] font-bold uppercase tracking-wider bg-amber-500/10 text-amber-400 border border-amber-500/20 px-3 py-1.5 rounded-lg hover:bg-amber-500/20 transition-all">+ Nova Análise</button>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {activeClient.phases.analysis.reports.filter(r => r.pirId === pir.id).map(report => (
                            <div key={report.id} className="p-5 bg-slate-800/30 rounded-xl border border-slate-800 hover:border-amber-500/30 transition-all group flex flex-col shadow-lg">
                               <div className="flex justify-between items-start mb-3">
                                  <div className="flex flex-col gap-1.5">
                                     <span className={`w-fit text-[9px] px-1.5 py-0.5 rounded font-bold border uppercase ${
                                       report.type === 'Strategic' ? 'bg-indigo-500/20 text-indigo-400 border-indigo-500/20' :
                                       report.type === 'Operational' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/20' :
                                       'bg-rose-500/20 text-rose-400 border-rose-500/20'
                                     }`}>{report.type}</span>
                                     <h5 className="font-bold text-slate-200 group-hover:text-amber-400 transition-colors leading-tight">{report.title}</h5>
                                  </div>
                               </div>
                               <p className="text-xs text-slate-400 line-clamp-4 leading-relaxed flex-1 mb-4 italic">"{report.content}"</p>
                               <div className="flex items-center justify-between mt-auto pt-4 border-t border-slate-800/50">
                                  <div className="flex items-center gap-2 text-[10px] text-slate-500 font-mono">
                                     <Calendar className="w-3.5 h-3.5" /> {new Date(report.date).toLocaleDateString()}
                                  </div>
                                  <div className="flex items-center gap-1.5">
                                     <button onClick={() => { setEditingAnalysis(report); setIsAnalysisModalOpen(true); }} className="p-2 hover:bg-slate-700 rounded text-slate-500 hover:text-white transition-all"><Edit2 className="w-4 h-4" /></button>
                                     <button onClick={() => handleDeleteAnalysis(report.id)} className="p-2 hover:bg-rose-500/10 rounded text-slate-500 hover:text-rose-400 transition-all"><Trash className="w-4 h-4" /></button>
                                  </div>
                               </div>
                            </div>
                          ))}
                          {activeClient.phases.analysis.reports.filter(r => r.pirId === pir.id).length === 0 && (
                            <div className="col-span-full py-6 text-xs text-slate-600 italic border border-dashed border-slate-800 rounded-xl text-center">Nenhuma análise produzida para este PIR.</div>
                          )}
                        </div>
                      </div>
                    ))}
                    {activeClient.phases.planning.pirs.length === 0 && (
                      <div className="py-20 text-center text-slate-600 italic border-2 border-dashed border-slate-800 rounded-2xl">
                        Defina os requisitos prioritários para iniciar a fase de análise.
                      </div>
                    )}
