        <div className="flex-1 overflow-y-auto px-10 py-10">
          {aiInsight && (
            <div className="mb-10 p-6 bg-indigo-600/5 border border-indigo-500/20 rounded-2xl flex gap-5 animate-in slide-in-from-top-4 duration-500 relative group overflow-hidden">
              <div className="absolute top-0 left-0 w-1 h-full bg-indigo-500"></div>
              <div className="bg-indigo-600/10 p-3 rounded-2xl h-fit">
                 <Sparkles className="w-6 h-6 text-indigo-400" />
              </div>
              <div className="flex-1">
                <h4 className="text-xs font-black text-indigo-400 uppercase tracking-widest mb-2">Insight de Inteligência Artificial</h4>
                <p className="text-sm text-indigo-100 leading-relaxed font-medium whitespace-pre-wrap">{aiInsight}</p>
                <div className="mt-4 flex gap-4">
                   <button className="text-[10px] font-black uppercase tracking-widest text-indigo-400 hover:text-indigo-300">Aplicar Recomendação</button>
                   <button className="text-[10px] font-black uppercase tracking-widest text-slate-600 hover:text-slate-500">Dispensar</button>
                </div>
              </div>
              <button onClick={() => setAiInsight(null)} className="shrink-0 text-slate-700 hover:text-white transition-colors p-1"><X className="w-5 h-5" /></button>
            </div>
          )}

          <div className="max-w-[1400px] mx-auto">
            {activePhase === 'dashboard' ? <Dashboard /> : activePhase === 'cases' ? <CasesManager /> : <PhaseView phase={activePhase as CTIPhase} />}
          </div>
        </div>
      </main>
    </div>
  );
}

