                <tr className="text-slate-500 border-b border-slate-800 uppercase tracking-wider text-[11px] font-bold">
                  <th className="py-4 px-6">PIR Associado</th>
                  <th className="py-4 px-6">TIPO DE CASO</th>
                  <th className="py-4 px-6">Status Precisão</th>
                  <th className="py-4 px-6">Resultado</th>
                  <th className="py-4 px-6 text-right">Gerenciar</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/50">
                {activeClient.metrics.map(m => (
                  <tr key={m.id} className="hover:bg-slate-800/30 transition-colors group">
                    <td className="py-4 px-6">
                       <div className="flex flex-col">
                          <span className="text-slate-200 font-bold">{activeClient.phases.planning.pirs.find(p => p.id === m.pirId)?.title || m.pirId}</span>
                          <span className="text-[10px] text-slate-500 uppercase font-mono mt-0.5">ID: {m.id}</span>
                       </div>
                    </td>
                    <td className="py-4 px-6">
                       {m.hasIncident ? (
                         <div className="flex flex-col">
                            <span className="text-rose-400 flex items-center gap-2 font-medium"><AlertTriangle className="w-3.5 h-3.5" /> Incidente Real</span>
                            <span className="text-[10px] text-slate-500 mt-0.5">{new Date(m.incidentDate!).toLocaleDateString()}</span>
                         </div>
                       ) : (
                         <div className="flex flex-col">
                            <span className="text-amber-400 flex items-center gap-2 font-medium"><Info className="w-3.5 h-3.5" /> Detecção Potencial</span>
                            <span className="text-[10px] text-slate-500 mt-0.5">{new Date(m.discoveryDate).toLocaleDateString()}</span>
                         </div>
                       )}
                    </td>
                    <td className="py-4 px-6">
                       {m.wasPreviouslyReported && m.hasIncident ? (
                         <span className="bg-emerald-500/10 text-emerald-400 px-2 py-0.5 rounded text-[10px] font-bold border border-emerald-500/20">ANTECIPADO</span>
                       ) : m.hasIncident ? (
                         <span className="bg-rose-500/10 text-rose-400 px-2 py-0.5 rounded text-[10px] font-bold border border-rose-500/20">NÃO MAPEADO</span>
                       ) : (
                         <span className="text-slate-600 italic text-[10px]">N/A</span>
                       )}
                    </td>
                    <td className="py-4 px-6">
                       <div className="flex items-center gap-2">
                          {!m.hasIncident ? (
                            <div className="flex items-center gap-1.5 text-amber-500 font-medium"><AlertCircle className="w-4 h-4" /> Potencial</div>
                          ) : m.incidentPrevented ? (
                            <div className="flex items-center gap-1.5 text-emerald-500 font-medium"><CheckCircle className="w-4 h-4" /> Mitigado</div>
                          ) : (
                            <div className="flex items-center gap-1.5 text-rose-500 font-medium"><X className="w-4 h-4" /> Consumado</div>
                          )}
                       </div>
                    </td>
                    <td className="py-4 px-6 text-right">
                       <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => { setEditingMetric(m); setIsMetricModalOpen(true); }} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400 hover:text-white transition-colors"><Edit2 className="w-4 h-4" /></button>
                          <button onClick={() => handleDeleteMetric(m.id)} className="p-2 hover:bg-rose-500/10 rounded-lg text-slate-500 hover:text-rose-400 transition-colors"><Trash className="w-4 h-4" /></button>
                       </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {activeClient.metrics.length === 0 && (
              <div className="py-24 text-center text-slate-600">
                <Activity className="w-16 h-16 mx-auto mb-4 opacity-10" />
                <p className="text-lg font-medium opacity-50">Nenhum caso registrado ainda.</p>
                <button onClick={() => setIsMetricModalOpen(true)} className="text-indigo-400 text-sm mt-2 hover:underline">Começar a registrar agora</button>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  };

  const Dashboard = () => {
    if (!activeClient) return null;
    const chartData = activeClient.metrics.map(m => {
      const diffHours = (d1: string, d2: string) => Math.max(0, (new Date(d1).getTime() - new Date(d2).getTime()) / (1000 * 60 * 60));
      return { date: new Date(m.discoveryDate).toLocaleDateString(), mttd: diffHours(m.discoveryDate, m.incidentDate || m.discoveryDate), mttdis: diffHours(m.disseminationDate, m.discoveryDate) };
    });
    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-10">
        <header className="mb-8">
          <h1 className="text-3xl font-bold text-white mb-2 tracking-tight">Status do Programa CTI</h1>
          <p className="text-slate-400">Indicadores chave de desempenho e eficácia operacional.</p>
        </header>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <StatCard title="MTTD Médio" value={`${performanceStats?.mttd || '0.0'}h`} color="blue" description="Detecção da Ameaça" />
          <StatCard title="MTTDis Médio" value={`${performanceStats?.mttdis || '0.0'}h`} color="purple" description="Disseminação Intel" />
          <StatCard title="Antecipação" value={`${performanceStats?.accuracy || '0'}%`} color="emerald" description="Casos já mapeados em PIRs" />
          <StatCard title="Mitigação" value={`${performanceStats?.prevention || '0'}%`} color="rose" description="Sucesso em prevenir danos" />
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl h-[350px] shadow-sm">
            <h3 className="text-xs font-bold text-slate-500 uppercase mb-6 flex items-center gap-2 tracking-widest"><Activity className="w-4 h-4 text-indigo-400" /> Histórico de Resposta (MTTD vs MTTDis)</h3>
            <ResponsiveContainer width="100%" height="80%">
              <AreaChart data={chartData}>
                <defs><linearGradient id="colorMttd" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/><stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/></linearGradient></defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} /><XAxis dataKey="date" stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} /><YAxis stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} /><Tooltip contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '8px', color: '#fff', fontSize: '12px' }} />
                <Area type="monotone" dataKey="mttd" stroke="#3b82f6" strokeWidth={2} fillOpacity={1} fill="url(#colorMttd)" name="MTTD (h)" /><Area type="monotone" dataKey="mttdis" stroke="#a855f7" strokeWidth={2} fillOpacity={0} fill="none" name="MTTDis (h)" /><Legend iconType="circle" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
          <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl h-[350px] shadow-sm">
            <h3 className="text-xs font-bold text-slate-500 uppercase mb-6 flex items-center gap-2 tracking-widest"><BarChart className="w-4 h-4 text-emerald-400" /> Distribuição de Impacto de Casos</h3>
            <ResponsiveContainer width="100%" height="80%">
              <ReBarChart data={[{ name: 'Baixo', count: activeClient.metrics.filter(m => m.impactScale === 'Low').length }, { name: 'Médio', count: activeClient.metrics.filter(m => m.impactScale === 'Medium').length }, { name: 'Alto', count: activeClient.metrics.filter(m => m.impactScale === 'High').length }, { name: 'Crítico', count: activeClient.metrics.filter(m => m.impactScale === 'Critical').length }]}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} /><XAxis dataKey="name" stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} /><YAxis stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} /><Tooltip cursor={{fill: '#1e293b', opacity: 0.5}} contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '8px', color: '#fff', fontSize: '12px' }} />
                <Bar dataKey="count" name="Quantidade de Casos" radius={[4, 4, 0, 0]}>{[0, 1, 2, 3].map((entry, index) => (<Cell key={`cell-${index}`} fill={['#94a3b8', '#fbbf24', '#f87171', '#7f1d1d'][index]} />))}</Bar>
              </ReBarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    );
  };

  const PhaseView = ({ phase }: { phase: CTIPhase }) => {
    const config = PHASE_CONFIG[phase];
    if (!activeClient) return null;
    const phaseIndex = PHASE_ORDER.indexOf(phase);
    const prevPhase = phaseIndex > 0 ? PHASE_ORDER[phaseIndex - 1] : null;
    const nextPhase = phaseIndex < PHASE_ORDER.length - 1 ? PHASE_ORDER[phaseIndex + 1] : null;
    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500 pb-24">
        <header className="mb-8 flex justify-between items-start">
          <div>
            <div className="flex items-center gap-3 mb-2"><div className={`p-2 bg-${config.color}-500/20 text-${config.color}-400 rounded-lg shadow-lg shadow-${config.color}-500/10`}>{config.icon}</div><h1 className="text-3xl font-bold text-white tracking-tight">{config.title}</h1></div>
            <p className="text-slate-400">Controle e registros da fase de {config.title.toLowerCase()}.</p>
          </div>
          <div className="flex items-center gap-2 bg-slate-900/50 p-1 rounded-xl border border-slate-800 backdrop-blur-sm">
             <button disabled={!prevPhase} onClick={() => setActivePhase(prevPhase!)} className="p-2 text-slate-500 hover:text-white disabled:opacity-20 transition-all rounded-lg hover:bg-slate-800"><ChevronLeft className="w-5 h-5" /></button>
             <button disabled={!nextPhase} onClick={() => setActivePhase(nextPhase!)} className="p-2 text-slate-500 hover:text-white disabled:opacity-20 transition-all rounded-lg hover:bg-slate-800"><ChevronRight className="w-5 h-5" /></button>
          </div>
        </header>
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <div className="lg:col-span-3 space-y-8">
            <div className="bg-slate-900/50 border border-slate-800 rounded-2xl overflow-hidden shadow-xl">
              <div className="px-6 py-4 border-b border-slate-800 flex justify-between items-center bg-slate-800/20">
                <h3 className="font-bold text-slate-200">{phase === 'dissemination' ? 'Registros de Disseminação' : phase === 'collection' ? 'Fontes de Inteligência por PIR' : phase === 'planning' ? 'Prioritários de Inteligência (PIRs)' : phase === 'analysis' ? 'Análises e Relatórios por PIR' : 'Registros da Fase'}</h3>
                {phase === 'dissemination' && <button onClick={() => { setIsDisseminationModalOpen(true); }} className="text-purple-400 hover:text-purple-300 text-sm flex items-center gap-1.5 font-bold bg-purple-400/10 px-4 py-2 rounded-xl border border-purple-400/20 transition-all hover:bg-purple-400/20"><Plus className="w-4 h-4" /> Novo Registro</button>}
                {phase === 'planning' && <button onClick={() => { setEditingPir(null); setIsPirModalOpen(true); }} className="text-blue-400 hover:text-blue-300 text-sm flex items-center gap-1.5 font-bold bg-blue-400/10 px-4 py-2 rounded-xl border border-blue-400/20 transition-all hover:bg-blue-400/20"><Plus className="w-4 h-4" /> Criar PIR</button>}
              </div>
              <div className="p-6">
                {phase === 'planning' && (
                   <div className="grid grid-cols-1 gap-4">
                      {activeClient.phases.planning.pirs.map(pir => (
                        <div key={pir.id} className={`bg-slate-800/30 rounded-2xl border border-slate-800 hover:border-blue-500/40 transition-all group overflow-hidden ${expandedPirId === pir.id ? 'border-blue-500/50' : ''}`}>
                           <div className="p-5 flex justify-between items-start cursor-pointer" onClick={() => setExpandedPirId(expandedPirId === pir.id ? null : pir.id)}>
                              <div className="flex-1 pr-10"><div className="flex items-center gap-2 mb-1"><h4 className="font-bold text-slate-100 group-hover:text-blue-400 transition-colors leading-tight">{pir.title}</h4><span className="text-[9px] font-mono text-slate-600 uppercase">ID: {pir.id}</span></div><p className="text-sm text-slate-400 line-clamp-1 leading-relaxed">{pir.description}</p></div>
                              <div className="flex items-center gap-4 shrink-0"><span className={`text-[10px] px-2 py-0.5 rounded font-bold border ${pir.priority === 'High' ? 'bg-rose-500/10 text-rose-400 border-rose-500/20' : 'bg-amber-500/10 text-amber-400 border-amber-500/20'}`}>{pir.priority}</span><div className="text-slate-600">{expandedPirId === pir.id ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}</div></div>
                           </div>
                           <div className="px-5 py-3 bg-slate-800/20 border-t border-slate-800 flex items-center gap-4">
                              <button onClick={(e) => { e.stopPropagation(); setEditingPir(pir); setIsPirModalOpen(true); }} className="text-[11px] font-bold text-slate-400 hover:text-white flex items-center gap-1.5 transition-colors"><Edit2 className="w-3.5 h-3.5" /> Editar</button>
                              {pir.status !== 'Archived' ? <button onClick={(e) => { e.stopPropagation(); handleArchivePir(pir.id); }} className="text-[11px] font-bold text-slate-400 hover:text-amber-400 flex items-center gap-1.5 transition-colors"><Archive className="w-3.5 h-3.5" /> Arquivar</button> : <button onClick={(e) => { e.stopPropagation(); handleRestorePir(pir.id); }} className="text-[11px] font-bold text-emerald-500 hover:text-emerald-400 flex items-center gap-1.5 transition-colors"><RefreshCw className="w-3.5 h-3.5" /> Reativar</button>}
                              <button onClick={(e) => { e.stopPropagation(); handleDeletePir(pir.id); }} className="text-[11px] font-bold text-slate-400 hover:text-rose-400 flex items-center gap-1.5 transition-colors ml-auto"><Trash className="w-3.5 h-3.5" /> Deletar</button>
                           </div>
                           {expandedPirId === pir.id && (
                             <div className="px-5 pb-6 pt-2 animate-in slide-in-from-top-2 duration-300">
                                <div className="border-t border-slate-800/50 pt-5 mt-2"><div className="flex items-center gap-2 mb-6"><History className="w-4 h-4 text-blue-400" /><h5 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Histórico de Ciclo de Vida</h5></div>
                                   <div className="space-y-6 relative ml-3"><div className="absolute left-0 top-0 bottom-0 w-0.5 bg-slate-800"></div>{(pir.history || []).slice().reverse().map((h, idx) => (
                                        <div key={idx} className="relative pl-6"><div className={`absolute -left-[5px] top-1.5 w-2.5 h-2.5 rounded-full ${idx === 0 ? 'bg-blue-500 shadow-lg shadow-blue-500/50' : 'bg-slate-700'}`}></div><div className="flex items-start justify-between"><div><span className={`text-[9px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded border mb-1.5 inline-block ${h.action === 'Created' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : h.action === 'Status Changed' ? 'bg-blue-500/10 text-blue-400 border-blue-500/20' : 'bg-slate-800 text-slate-400 border-slate-700'}`}>{h.action}</span><p className="text-xs text-slate-300 font-medium">Status definido para: <span className="text-slate-100 font-bold">{h.status}</span></p></div><div className="text-[10px] text-slate-600 font-mono">{new Date(h.date).toLocaleString('pt-BR')}</div></div></div>
                                      ))}{(!pir.history || pir.history.length === 0) && <p className="text-xs text-slate-600 italic pl-6">Nenhum histórico registrado para este requisito.</p>}</div>
                                </div>
                             </div>
                           )}
                        </div>
                      ))}
                   </div>
                )}
                {phase === 'collection' && (
                  <div className="space-y-12">
                    {activeClient.phases.planning.pirs.map(pir => (
                      <div key={pir.id} className="space-y-4">
                        <div className="flex justify-between items-center border-b border-slate-800 pb-2"><h4 className="font-bold text-emerald-400 flex items-center gap-2"><LinkIcon className="w-4 h-4" /> {pir.title}</h4><button onClick={() => { setSourceModalPirId(pir.id); setEditingSource(null); setIsSourceModalOpen(true); }} className="text-[10px] font-bold uppercase tracking-wider bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 px-3 py-1.5 rounded-lg hover:bg-emerald-500/20 transition-all">+ Nova Fonte</button></div>
                        <div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead><tr className="text-slate-600 uppercase text-[10px] tracking-widest font-bold"><th className="pb-4 pr-4">Fonte / Ativo</th><th className="pb-4 pr-4">Tipo</th><th className="pb-4 pr-4">Confiança</th><th className="pb-4 pr-4 text-center">Rel.</th><th className="pb-4 text-right">Ações</th></tr></thead><tbody className="divide-y divide-slate-800/30">{activeClient.phases.collection.sources.filter(s => s.pirId === pir.id).map(source => (<tr key={source.id} className="group hover:bg-slate-800/20 transition-colors"><td className="py-4 pr-4 font-bold text-slate-300">{source.name}</td><td className="py-4 pr-4"><span className="text-[10px] text-slate-500 border border-slate-800 px-1.5 py-0.5 rounded">{source.type === 'FeedComercial' ? 'Feed Comercial' : source.type === 'FeedAberto' ? 'Feed aberto' : source.type}</span></td><td className="py-4 pr-4"><div className="flex items-center gap-3"><div className="flex-1 h-1.5 bg-slate-800 rounded-full min-w-[80px] overflow-hidden"><div className="h-full bg-emerald-500 transition-all duration-1000" style={{ width: `${source.confidence}%` }}></div></div><span className="text-[10px] font-mono text-slate-500">{source.confidence}%</span></div></td><td className="py-4 pr-4 text-center text-xs font-bold text-indigo-400">{source.reliability}</td><td className="py-4 text-right"><div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => { setEditingSource(source); setIsSourceModalOpen(true); }} className="p-1.5 hover:bg-slate-700 rounded text-slate-400 hover:text-white transition-all"><Edit2 className="w-3.5 h-3.5" /></button><button onClick={() => handleDeleteSource(source.id)} className="p-1.5 hover:bg-rose-500/10 rounded text-slate-400 hover:text-rose-400 transition-all"><Trash className="w-3.5 h-3.5" /></button></div></td></tr>))}{activeClient.phases.collection.sources.filter(s => s.pirId === pir.id).length === 0 && (<tr><td colSpan={5} className="py-8 text-sm text-slate-600 italic text-center">Nenhuma fonte vinculada a este requisito de inteligência.</td></tr>)}</tbody></table></div>
                      </div>
                    ))}
                  </div>
                )}
                {phase === 'analysis' && (
                  <div className="space-y-12">
                    {activeClient.phases.planning.pirs.map(pir => (
                      <div key={pir.id} className="space-y-4">
                        <div className="flex justify-between items-center border-b border-slate-800 pb-2"><h4 className="font-bold text-amber-400 flex items-center gap-2"><BookOpen className="w-4 h-4" /> {pir.title}</h4><button onClick={() => { setAnalysisModalPirId(pir.id); setEditingAnalysis(null); setIsAnalysisModalOpen(true); }} className="text-[10px] font-bold uppercase tracking-wider bg-amber-500/10 text-amber-400 border border-amber-500/20 px-3 py-1.5 rounded-lg hover:bg-amber-500/20 transition-all">+ Nova Análise</button></div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">{activeClient.phases.analysis.reports.filter(r => r.pirId === pir.id).map(report => (<div key={report.id} className="p-5 bg-slate-800/30 rounded-xl border border-slate-800 hover:border-amber-500/30 transition-all group flex flex-col shadow-lg"><div className="flex justify-between items-start mb-3"><div className="flex flex-col gap-1.5"><span className={`w-fit text-[9px] px-1.5 py-0.5 rounded font-bold border uppercase ${report.type === 'Strategic' ? 'bg-indigo-500/20 text-indigo-400 border-indigo-500/20' : report.type === 'Operational' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/20' : 'bg-rose-500/20 text-rose-400 border-rose-500/20'}`}>{report.type}</span><h5 className="font-bold text-slate-200 group-hover:text-amber-400 transition-colors leading-tight">{report.title}</h5></div></div><p className="text-xs text-slate-400 line-clamp-4 leading-relaxed flex-1 mb-4 italic">"{report.content}"</p><div className="flex items-center justify-between mt-auto pt-4 border-t border-slate-800/50"><div className="flex items-center gap-2 text-[10px] text-slate-500 font-mono"><Calendar className="w-3.5 h-3.5" /> {new Date(report.date).toLocaleDateString()}</div><div className="flex items-center gap-1.5"><button onClick={() => { setEditingAnalysis(report); setIsAnalysisModalOpen(true); }} className="p-2 hover:bg-slate-700 rounded text-slate-500 hover:text-white transition-all"><Edit2 className="w-4 h-4" /></button><button onClick={() => handleDeleteAnalysis(report.id)} className="p-2 hover:bg-rose-500/10 rounded text-slate-500 hover:text-rose-400 transition-all"><Trash className="w-4 h-4" /></button></div></div></div>))}{activeClient.phases.analysis.reports.filter(r => r.pirId === pir.id).length === 0 && (<div className="col-span-full py-6 text-xs text-slate-600 italic border border-dashed border-slate-800 rounded-xl text-center">Nenhuma análise produzida para este PIR.</div>)}</div>
                      </div>
                    ))}
                  </div>
                )}
                {phase === 'dissemination' && (
                  <div className="space-y-4">
                    {activeClient.phases.dissemination.logs.map(log => (<div key={log.id} className="p-4 bg-slate-800/30 rounded-xl border border-slate-800 hover:border-purple-500/40 transition-all group shadow-md"><div className="flex justify-between items-start"><div className="flex-1"><div className="flex items-center gap-3 mb-2"><span className="text-[10px] font-mono text-slate-500 flex items-center gap-1.5"><Calendar className="w-3.5 h-3.5" /> {new Date(log.date).toLocaleDateString()}</span><span className={`text-[9px] px-2 py-0.5 rounded font-bold border ${log.type === 'Strategic' ? 'bg-indigo-500/20 text-indigo-400 border-indigo-500/30' : log.type === 'Operational' ? 'bg-amber-500/20 text-amber-400 border-amber-500/30' : 'bg-rose-500/20 text-rose-400 border-rose-500/30'}`}>{log.type}</span></div><h4 className="font-bold text-slate-100 flex items-center gap-2 mb-2"><FileText className="w-4 h-4 text-purple-400" /> {log.reportName}</h4>{log.observations && <p className="text-sm text-slate-400 leading-relaxed border-l-2 border-slate-800 pl-3 italic">"{log.observations}"</p>}</div><div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button className="p-2 hover:bg-slate-700 rounded text-slate-500 hover:text-white"><Eye className="w-4 h-4" /></button><button className="p-2 hover:bg-rose-500/10 rounded text-slate-500 hover:text-rose-400"><Trash className="w-4 h-4" /></button></div></div></div>))}
                  </div>
                )}
              </div>
            </div>
          </div>
          <div className="space-y-6"><div className="bg-slate-900/80 border border-slate-800 rounded-2xl p-6 shadow-xl sticky top-24"><h4 className="text-[10px] font-bold text-slate-500 uppercase mb-6 tracking-widest border-b border-slate-800 pb-3">Fluxo de Inteligência</h4><div className="space-y-8"><div className="relative pl-6 border-l-2 border-slate-800 group"><div className={`absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-slate-900 border-2 border-indigo-500 group-hover:scale-110 transition-transform`}></div><h5 className="text-indigo-400 text-[10px] font-bold uppercase mb-2">Entradas (Inputs)</h5><ul className="space-y-2">{config.inputs.map(i => <li key={i} className="text-xs text-slate-400 leading-relaxed">• {i}</li>)}</ul></div><div className="relative pl-6 border-l-2 border-slate-800 group"><div className={`absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-slate-900 border-2 border-emerald-500 group-hover:scale-110 transition-transform`}></div><h5 className="text-emerald-400 text-[10px] font-bold uppercase mb-2">Saídas (Outputs)</h5><ul className="space-y-2">{config.outputs.map(o => <li key={o} className="text-xs text-slate-400 leading-relaxed">• {o}</li>)}</ul></div></div></div></div>
        </div>
      </div>
    );
  };

  const NavItem = ({ active, onClick, icon, label, color = 'indigo' }: any) => {
    const variant = COLOR_VARIANTS[color] || COLOR_VARIANTS.indigo;
    return (<button onClick={onClick} className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all group ${active ? `${variant.bg} ${variant.text} border ${variant.border} shadow-lg shadow-${color}-500/5` : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'}`}><div className={`shrink-0 ${active ? variant.text : 'text-slate-500 group-hover:text-slate-300'}`}>{icon}</div><span className="text-sm font-bold tracking-tight">{label}</span></button>);
  }

  const StatCard = ({ title, value, color, description }: any) => {
    const variant = COLOR_VARIANTS[color] || COLOR_VARIANTS.indigo;
    return (<div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl hover:border-slate-600 transition-all shadow-xl group"><p className="text-[10px] font-bold text-slate-500 uppercase mb-2 tracking-widest">{title}</p><div className="flex items-baseline gap-2"><span className="text-3xl font-bold text-white group-hover:scale-105 transition-transform inline-block origin-left">{value}</span></div>{description && <p className="text-[11px] text-slate-500 mt-2 font-medium">{description}</p>}</div>);
  }

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-950 text-slate-100">
      {isMetricModalOpen && <MetricEntryModal />}
      {isDisseminationModalOpen && <DisseminationModal />}
      {isPirModalOpen && <PirModal />}
      {isSourceModalOpen && <SourceModal />}
      {isAnalysisModalOpen && <AnalysisModal />}
      <aside className={`bg-slate-900/80 border-r border-slate-800 transition-all duration-500 flex flex-col z-20 backdrop-blur-xl ${isSidebarOpen ? 'w-72' : 'w-0 -translate-x-full overflow-hidden'}`}>
        <div className="p-8 flex items-center gap-4 border-b border-slate-800/50"><div className="bg-indigo-600 p-2.5 rounded-2xl shadow-lg shadow-indigo-600/20"><Shield className="w-6 h-6 text-white" /></div><span className="font-black text-2xl tracking-tighter text-white">CTI SENTINEL</span></div>
        <div className="px-5 py-8 flex-1 space-y-8 overflow-y-auto">
          <div><label className="text-[10px] font-black text-slate-500 uppercase px-3 mb-4 block tracking-widest">Organização</label><div className="space-y-1.5">{clients.map(c => (<button key={c.id} onClick={() => setActiveClientId(c.id)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all truncate ${activeClientId === c.id ? 'bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 shadow-lg shadow-indigo-500/5' : 'text-slate-400 hover:bg-slate-800 hover:text-slate-300'}`}><div className={`w-2 h-2 rounded-full ${activeClientId === c.id ? 'bg-indigo-400 animate-pulse' : 'bg-slate-700'}`}></div>{c.name}</button>))}<button className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-xs text-slate-600 font-bold border border-dashed border-slate-800 hover:border-slate-700 hover:text-slate-500 transition-all mt-2"><Plus className="w-4 h-4" /> Novo Cliente</button></div></div>
          <nav className="space-y-8"><div><label className="text-[10px] font-black text-slate-500 uppercase px-3 mb-4 block tracking-widest">Navegação</label><div className="space-y-1"><NavItem active={activePhase === 'dashboard'} onClick={() => setActivePhase('dashboard')} icon={<LayoutDashboard className="w-5 h-5" />} label="Visão Geral" /><NavItem active={activePhase === 'cases'} onClick={() => setActivePhase('cases')} icon={<Activity className="w-5 h-5" />} label="Gestão de Casos" color="rose" /></div></div><div><label className="text-[10px] font-black text-slate-500 uppercase px-3 mb-4 block tracking-widest">Ciclo de Inteligência</label><div className="space-y-1">{(Object.keys(PHASE_CONFIG) as CTIPhase[]).filter(p => p !== 'metrics').map(p => (<NavItem key={p} active={activePhase === p} onClick={() => setActivePhase(p)} icon={PHASE_CONFIG[p].icon} label={PHASE_CONFIG[p].title.split(' ')[0]} color={PHASE_CONFIG[p].color} />))}</div></div></nav>
        </div>
      </aside>
      <main className="flex-1 flex flex-col min-w-0 bg-slate-950 relative">
        <header className="h-20 border-b border-slate-800/50 px-10 flex items-center justify-between bg-slate-950/50 backdrop-blur-xl sticky top-0 z-10">
          <div className="flex items-center gap-6"><button onClick={toggleSidebar} className="p-2.5 bg-slate-900 border border-slate-800 hover:border-slate-700 rounded-xl text-slate-400 hover:text-white transition-all shadow-sm">{isSidebarOpen ? <ArrowLeft className="w-5 h-5" /> : <Menu className="w-5 h-5" />}</button><div className="flex items-center gap-2 text-sm font-medium"><span className="text-slate-500">CTI Program</span><ChevronRight className="w-4 h-4 text-slate-800" /><span className="text-slate-100 font-bold">{activeClient?.name}</span></div></div>
          <div className="flex items-center gap-4"><button disabled={loadingAi} className="flex items-center gap-2.5 bg-indigo-600 hover:bg-indigo-500 text-white px-5 py-2.5 rounded-xl text-xs font-black tracking-widest uppercase transition-all shadow-lg shadow-indigo-600/20 active:scale-95 disabled:opacity-50" onClick={handleAiInsight}>{loadingAi ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />} Analista IA</button></div>
        </header>
        <div className="flex-1 overflow-y-auto px-10 py-10">
          {aiInsight && (<div className="mb-10 p-6 bg-indigo-600/5 border border-indigo-500/20 rounded-2xl flex gap-5 animate-in slide-in-from-top-4 duration-500 relative group overflow-hidden"><div className="absolute top-0 left-0 w-1 h-full bg-indigo-500"></div><div className="bg-indigo-600/10 p-3 rounded-2xl h-fit"><Sparkles className="w-6 h-6 text-indigo-400" /></div><div className="flex-1"><h4 className="text-xs font-black text-indigo-400 uppercase tracking-widest mb-2">Insight de Inteligência Artificial</h4><p className="text-sm text-indigo-100 leading-relaxed font-medium whitespace-pre-wrap">{aiInsight}</p></div><button onClick={() => setAiInsight(null)} className="shrink-0 text-slate-700 hover:text-white transition-colors p-1"><X className="w-5 h-5" /></button></div>)}
          <div className="max-w-[1400px] mx-auto">{activePhase === 'dashboard' ? <Dashboard /> : activePhase === 'cases' ? <CasesManager /> : <PhaseView phase={activePhase as CTIPhase} />}</div>
        </div>
      </main>
    </div>
  );
}

