              <ReBarChart data={[{ name: 'Baixo', count: activeClient.metrics.filter(m => m.impactScale === 'Low').length }, { name: 'Médio', count: activeClient.metrics.filter(m => m.impactScale === 'Medium').length }, { name: 'Alto', count: activeClient.metrics.filter(m => m.impactScale === 'High').length }, { name: 'Crítico', count: activeClient.metrics.filter(m => m.impactScale === 'Critical').length }]}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} /><XAxis dataKey="name" stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} /><YAxis stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} /><Tooltip cursor={{fill: '#1e293b', opacity: 0.5}} contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '8px', color: '#fff', fontSize: '12px' }} />
                <Bar dataKey="count" name="Quantidade de Casos" radius={[4, 4, 0, 0]}>{[0, 1, 2, 3].map((entry, index) => (<Cell key={`cell-${index}`} fill={['#94a3b8', '#fbbf24', '#f87171', '#7f1d1d'][index]} />))}</Bar>
              </ReBarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    );
  };

  const PhaseView = ({ phase }: { phase: CTIPhase }) => {
    const config = PHASE_CONFIG[phase];
    if (!activeClient) return null;
    const phaseIndex = PHASE_ORDER.indexOf(phase);
    const prevPhase = phaseIndex > 0 ? PHASE_ORDER[phaseIndex - 1] : null;
    const nextPhase = phaseIndex < PHASE_ORDER.length - 1 ? PHASE_ORDER[phaseIndex + 1] : null;
    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500 pb-24">
        <header className="mb-8 flex justify-between items-start">
          <div>
            <div className="flex items-center gap-3 mb-2"><div className={`p-2 bg-${config.color}-500/20 text-${config.color}-400 rounded-lg shadow-lg shadow-${config.color}-500/10`}>{config.icon}</div><h1 className="text-3xl font-bold text-white tracking-tight">{config.title}</h1></div>
            <p className="text-slate-400">Controle e registros da fase de {config.title.toLowerCase()}.</p>
          </div>
          <div className="flex items-center gap-2 bg-slate-900/50 p-1 rounded-xl border border-slate-800 backdrop-blur-sm">
             <button disabled={!prevPhase} onClick={() => setActivePhase(prevPhase!)} className="p-2 text-slate-500 hover:text-white disabled:opacity-20 transition-all rounded-lg hover:bg-slate-800"><ChevronLeft className="w-5 h-5" /></button>
             <button disabled={!nextPhase} onClick={() => setActivePhase(nextPhase!)} className="p-2 text-slate-500 hover:text-white disabled:opacity-20 transition-all rounded-lg hover:bg-slate-800"><ChevronRight className="w-5 h-5" /></button>
          </div>
        </header>
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <div className="lg:col-span-3 space-y-8">
            <div className="bg-slate-900/50 border border-slate-800 rounded-2xl overflow-hidden shadow-xl">
              <div className="px-6 py-4 border-b border-slate-800 flex justify-between items-center bg-slate-800/20">
                <h3 className="font-bold text-slate-200">{phase === 'dissemination' ? 'Registros de Disseminação' : phase === 'collection' ? 'Fontes de Inteligência por PIR' : phase === 'planning' ? 'Prioritários de Inteligência (PIRs)' : phase === 'analysis' ? 'Análises e Relatórios por PIR' : 'Registros da Fase'}</h3>
                {phase === 'dissemination' && <button onClick={() => { setIsDisseminationModalOpen(true); }} className="text-purple-400 hover:text-purple-300 text-sm flex items-center gap-1.5 font-bold bg-purple-400/10 px-4 py-2 rounded-xl border border-purple-400/20 transition-all hover:bg-purple-400/20"><Plus className="w-4 h-4" /> Novo Registro</button>}
                {phase === 'planning' && <button onClick={() => { setEditingPir(null); setIsPirModalOpen(true); }} className="text-blue-400 hover:text-blue-300 text-sm flex items-center gap-1.5 font-bold bg-blue-400/10 px-4 py-2 rounded-xl border border-purple-400/20 transition-all hover:bg-blue-400/20"><Plus className="w-4 h-4" /> Criar PIR</button>}
              </div>
              <div className="p-6">
                {phase === 'planning' && (
                   <div className="grid grid-cols-1 gap-4">
                      {activeClient.phases.planning.pirs.map(pir => (
                        <div key={pir.id} className={`bg-slate-800/30 rounded-2xl border border-slate-800 hover:border-blue-500/40 transition-all group overflow-hidden ${expandedPirId === pir.id ? 'border-blue-500/50' : ''}`}>
                           <div className="p-5 flex justify-between items-start cursor-pointer" onClick={() => setExpandedPirId(expandedPirId === pir.id ? null : pir.id)}>
                              <div className="flex-1 pr-10"><div className="flex items-center gap-2 mb-1"><h4 className="font-bold text-slate-100 group-hover:text-blue-400 transition-colors leading-tight">{pir.title}</h4><span className="text-[9px] font-mono text-slate-600 uppercase">ID: {pir.id}</span></div><p className="text-sm text-slate-400 line-clamp-1 leading-relaxed">{pir.description}</p></div>
                              <div className="flex items-center gap-4 shrink-0"><span className={`text-[10px] px-2 py-0.5 rounded font-bold border ${pir.priority === 'High' ? 'bg-rose-500/10 text-rose-400 border-rose-500/20' : 'bg-amber-500/10 text-amber-400 border-amber-500/20'}`}>{pir.priority}</span><div className="text-slate-600">{expandedPirId === pir.id ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}</div></div>
                           </div>
                           <div className="px-5 py-3 bg-slate-800/20 border-t border-slate-800 flex items-center gap-4">
                              <button onClick={(e) => { e.stopPropagation(); setEditingPir(pir); setIsPirModalOpen(true); }} className="text-[11px] font-bold text-slate-400 hover:text-white flex items-center gap-1.5 transition-colors"><Edit2 className="w-3.5 h-3.5" /> Editar</button>
                              {pir.status !== 'Archived' ? <button onClick={(e) => { e.stopPropagation(); handleArchivePir(pir.id); }} className="text-[11px] font-bold text-slate-400 hover:text-amber-400 flex items-center gap-1.5 transition-colors"><Archive className="w-3.5 h-3.5" /> Arquivar</button> : <button onClick={(e) => { e.stopPropagation(); handleRestorePir(pir.id); }} className="text-[11px] font-bold text-emerald-500 hover:text-emerald-400 flex items-center gap-1.5 transition-colors"><RefreshCw className="w-3.5 h-3.5" /> Reativar</button>}
                              <button onClick={(e) => { e.stopPropagation(); handleDeletePir(pir.id); }} className="text-[11px] font-bold text-slate-400 hover:text-rose-400 flex items-center gap-1.5 transition-colors ml-auto"><Trash className="w-3.5 h-3.5" /> Deletar</button>
                           </div>
                           {expandedPirId === pir.id && (
                             <div className="px-5 pb-6 pt-2 animate-in slide-in-from-top-2 duration-300">
                                <div className="border-t border-slate-800/50 pt-5 mt-2"><div className="flex items-center gap-2 mb-6"><History className="w-4 h-4 text-blue-400" /><h5 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Histórico de Ciclo de Vida</h5></div>
                                   <div className="space-y-6 relative ml-3"><div className="absolute left-0 top-0 bottom-0 w-0.5 bg-slate-800"></div>{(pir.history || []).slice().reverse().map((h, idx) => (
                                        <div key={idx} className="relative pl-6"><div className={`absolute -left-[5px] top-1.5 w-2.5 h-2.5 rounded-full ${idx === 0 ? 'bg-blue-500 shadow-lg shadow-blue-500/50' : 'bg-slate-700'}`}></div><div className="flex items-start justify-between"><div><span className={`text-[9px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded border mb-1.5 inline-block ${h.action === 'Created' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : h.action === 'Status Changed' ? 'bg-blue-500/10 text-blue-400 border-blue-500/20' : 'bg-slate-800 text-slate-400 border-slate-700'}`}>{h.action}</span><p className="text-xs text-slate-300 font-medium">Status definido para: <span className="text-slate-100 font-bold">{h.status}</span></p></div><div className="text-[10px] text-slate-600 font-mono">{new Date(h.date).toLocaleString('pt-BR')}</div></div></div>
                                      ))}{(!pir.history || pir.history.length === 0) && <p className="text-xs text-slate-600 italic pl-6">Nenhum histórico registrado para este requisito.</p>}</div>
                                </div>
                             </div>
