    const mapConfidenceToReliability = (conf: number): IntelligenceSource['reliability'] => {
      if (conf <= 20) return 'E';
      if (conf <= 39) return 'D';
      if (conf <= 59) return 'C';
      if (conf <= 89) return 'B';
      return 'A';
    };

    const mapReliabilityToConfidence = (rel: IntelligenceSource['reliability']): number => {
      switch (rel) {
        case 'E': return 10;
        case 'D': return 30;
        case 'C': return 50;
        case 'B': return 75;
        case 'A': return 95;
        default: return 50;
      }
    };

    const handleConfidenceChange = (val: number) => {
      setForm(prev => ({
        ...prev,
        confidence: val,
        reliability: mapConfidenceToReliability(val)
      }));
    };

    const handleReliabilityChange = (rel: IntelligenceSource['reliability']) => {
      setForm(prev => ({
        ...prev,
        reliability: rel,
        confidence: mapReliabilityToConfidence(rel)
