                      <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Contato</span>
                      <div className="flex items-center gap-2">
                        <Mail className="w-3 h-3 text-indigo-400" />
                        <span className="text-xs font-bold text-slate-300">{activeClient.stakeholderEmail}</span>
