        </header>

        {activeClient.description && (
          <div className="bg-indigo-500/5 border border-indigo-500/10 p-5 rounded-2xl">
             <p className="text-sm text-slate-400 leading-relaxed italic"><Info className="w-4 h-4 inline mr-2 text-indigo-400" /> {activeClient.description}</p>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <StatCard title="MTTD Médio" value={`${performanceStats?.mttd || '0.0'}h`} color="blue" description="Detecção da Ameaça" />
          <StatCard title="MTTDis Médio" value={`${performanceStats?.mttdis || '0.0'}h`} color="purple" description="Disseminação Intel" />
          <StatCard title="Antecipação" value={`${performanceStats?.accuracy || '0'}%`} color="emerald" description="Casos já mapeados em PIRs" />
          <StatCard title="Mitigação" value={`${performanceStats?.prevention || '0'}%`} color="rose" description="Sucesso em prevenir danos" />
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl h-[350px] shadow-sm">
            <h3 className="text-xs font-bold text-slate-500 uppercase mb-6 flex items-center gap-2 tracking-widest"><Activity className="w-4 h-4 text-indigo-400" /> Histórico de Resposta (MTTD vs MTTDis)</h3>
            <ResponsiveContainer width="100%" height="80%">
              <AreaChart data={chartData}>
                <defs><linearGradient id="colorMttd" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/><stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/></linearGradient></defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} /><XAxis dataKey="date" stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} /><YAxis stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} /><Tooltip contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '8px', color: '#fff', fontSize: '12px' }} />
                <Area type="monotone" dataKey="mttd" stroke="#3b82f6" strokeWidth={2} fillOpacity={1} fill="url(#colorMttd)" name="MTTD (h)" /><Area type="monotone" dataKey="mttdis" stroke="#a855f7" strokeWidth={2} fillOpacity={0} fill="none" name="MTTDis (h)" /><Legend iconType="circle" />
