> s.pirId === pir.id).length === 0 && (<tr><td colSpan={5} className="py-8 text-sm text-slate-600 italic text-center">Nenhuma fonte vinculada a este requisito de inteligência.</td></tr>)}</tbody></table></div>
                      </div>
                    ))}
                  </div>
                )}
                {phase === 'analysis' && (
                  <div className="space-y-12">
                    {activeClient.phases.planning.pirs.map(pir => (
                      <div key={pir.id} className="space-y-4">
                        <div className="flex justify-between items-center border-b border-slate-800 pb-2"><h4 className="font-bold text-amber-400 flex items-center gap-2"><BookOpen className="w-4 h-4" /> {pir.title}</h4><button onClick={() => { setAnalysisModalPirId(pir.id); setEditingAnalysis(null); setIsAnalysisModalOpen(true); }} className="text-[10px] font-bold uppercase tracking-wider bg-amber-500/10 text-amber-400 border border-amber-500/20 px-3 py-1.5 rounded-lg hover:bg-amber-500/20 transition-all">+ Nova Análise</button></div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">{activeClient.phases.analysis.reports.filter(r => r.pirId === pir.id).map(report => (<div key={report.id} className="p-5 bg-slate-800/30 rounded-xl border border-slate-800 hover:border-amber-500/30 transition-all group flex flex-col shadow-lg"><div className="flex justify-between items-start mb-3"><div className="flex flex-col gap-1.5"><span className={`w-fit text-[9px] px-1.5 py-0.5 rounded font-bold border uppercase ${report.type === 'Strategic' ? 'bg-indigo-500/20 text-indigo-400 border-indigo-500/20' : report.type === 'Operational' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/20' : 'bg-rose-500/20 text-rose-400 border-rose-500/20'}`}>{report.type}</span><h5 className="font-bold text-slate-200 group-hover:text-amber-400 transition-colors leading-tight">{report.title}</h5></div></div><p className="text-xs text-slate-400 line-clamp-4 leading-relaxed flex-1 mb-4 italic">"{report.content}"</p><div className="flex items-center justify-between mt-auto pt-4 border-t border-slate-800/50"><div className="flex items-center gap-2 text-[10px] text-slate-500 font-mono"><Calendar className="w-3.5 h-3.5" /> {new Date(report.date).toLocaleDateString()}</div><div className="flex items-center gap-1.5"><button onClick={() => { setEditingAnalysis(report); setIsAnalysisModalOpen(true); }} className="p-2 hover:bg-slate-700 rounded text-slate-500 hover:text-white transition-all"><Edit2 className="w-4 h-4" /></button><button onClick={() => handleDeleteAnalysis(report.id)} className="p-2 hover:bg-rose-500/10 rounded text-slate-500 hover:text-rose-400 transition-all"><Trash className="w-4 h-4" /></button></div></div></div>))}{activeClient.phases.analysis.reports.filter(r => r.pirId === pir.id).length === 0 && (<div className="col-span-full py-6 text-xs text-slate-600 italic border border-dashed border-slate-800 rounded-xl text-center">Nenhuma análise produzida para este PIR.</div>)}</div>
                      </div>
                    ))}
                  </div>
                )}
                {phase === 'dissemination' && (
                  <div className="space-y-4">
                    {activeClient.phases.dissemination.logs.map(log => (<div key={log.id} className="p-4 bg-slate-800/30 rounded-xl border border-slate-800 hover:border-purple-500/40 transition-all group shadow-md"><div className="flex justify-between items-start"><div className="flex-1"><div className="flex items-center gap-3 mb-2"><span className="text-[10px] font-mono text-slate-500 flex items-center gap-1.5"><Calendar className="w-3.5 h-3.5" /> {new Date(log.date).toLocaleDateString()}</span><span className={`text-[9px] px-2 py-0.5 rounded font-bold border ${log.type === 'Strategic' ? 'bg-indigo-500/20 text-indigo-400 border-indigo-500/30' : log.type === 'Operational' ? 'bg-amber-500/20 text-amber-400 border-amber-500/30' : 'bg-rose-500/20 text-rose-400 border-rose-500/30'}`}>{log.type}</span></div><h4 className="font-bold text-slate-100 flex items-center gap-2 mb-2"><FileText className="w-4 h-4 text-purple-400" /> {log.reportName}</h4>{log.observations && <p className="text-sm text-slate-400 leading-relaxed border-l-2 border-slate-800 pl-3 italic">"{log.observations}"</p>}</div><div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button className="p-2 hover:bg-slate-700 rounded text-slate-500 hover:text-white"><Eye className="w-4 h-4" /></button><button className="p-2 hover:bg-rose-500/10 rounded text-slate-500 hover:text-rose-400"><Trash className="w-4 h-4" /></button></div></div></div>))}
