                )}
              </div>
            </div>
          </div>
          <div className="space-y-6"><div className="bg-slate-900/80 border border-slate-800 rounded-2xl p-6 shadow-xl sticky top-24"><h4 className="text-[10px] font-bold text-slate-500 uppercase mb-6 tracking-widest border-b border-slate-800 pb-3">Fluxo de Inteligência</h4><div className="space-y-8"><div className="relative pl-6 border-l-2 border-slate-800 group"><div className={`absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-slate-900 border-2 border-indigo-500 group-hover:scale-110 transition-transform`}></div><h5 className="text-indigo-400 text-[10px] font-bold uppercase mb-2">Entradas (Inputs)</h5><ul className="space-y-2">{config.inputs.map(i => <li key={i} className="text-xs text-slate-400 leading-relaxed">• {i}</li>)}</ul></div><div className="relative pl-6 border-l-2 border-slate-800 group"><div className={`absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-slate-900 border-2 border-emerald-500 group-hover:scale-110 transition-transform`}></div><h5 className="text-emerald-400 text-[10px] font-bold uppercase mb-2">Saídas (Outputs)</h5><ul className="space-y-2">{config.outputs.map(o => <li key={o} className="text-xs text-slate-400 leading-relaxed">• {o}</li>)}</ul></div></div></div></div>
        </div>
      </div>
    );
  };

  const NavItem = ({ active, onClick, icon, label, color = 'indigo' }: any) => {
    const variant = COLOR_VARIANTS[color] || COLOR_VARIANTS.indigo;
    return (<button onClick={onClick} className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all group ${active ? `${variant.bg} ${variant.text} border ${variant.border} shadow-lg shadow-${color}-500/5` : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'}`}><div className={`shrink-0 ${active ? variant.text : 'text-slate-500 group-hover:text-slate-300'}`}>{icon}</div><span className="text-sm font-bold tracking-tight">{label}</span></button>);
  }

  const StatCard = ({ title, value, color, description }: any) => {
    const variant = COLOR_VARIANTS[color] || COLOR_VARIANTS.indigo;
    return (<div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl hover:border-slate-600 transition-all shadow-xl group"><p className="text-[10px] font-bold text-slate-500 uppercase mb-2 tracking-widest">{title}</p><div className="flex items-baseline gap-2"><span className="text-3xl font-bold text-white group-hover:scale-105 transition-transform inline-block origin-left">{value}</span></div>{description && <p className="text-[11px] text-slate-500 mt-2 font-medium">{description}</p>}</div>);
  }

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-950 text-slate-100">
      {isMetricModalOpen && <MetricEntryModal />}
      {isDisseminationModalOpen && <DisseminationModal />}
      {isPirModalOpen && <PirModal />}
      {isSourceModalOpen && <SourceModal />}
      {isAnalysisModalOpen && <AnalysisModal />}
      {isOrgModalOpen && <OrgModal />}

      <aside className={`bg-slate-900/80 border-r border-slate-800 transition-all duration-500 flex flex-col z-20 backdrop-blur-xl ${isSidebarOpen ? 'w-72' : 'w-0 -translate-x-full overflow-hidden'}`}>
        <div className="p-8 flex items-center gap-4 border-b border-slate-800/50"><div className="bg-indigo-600 p-2.5 rounded-2xl shadow-lg shadow-indigo-600/20"><Shield className="w-6 h-6 text-white" /></div><span className="font-black text-2xl tracking-tighter text-white">CTI SENTINEL</span></div>
        <div className="px-5 py-8 flex-1 space-y-8 overflow-y-auto">
          <div>
            <label className="text-[10px] font-black text-slate-500 uppercase px-3 mb-4 block tracking-widest">Organização</label>
            <div className="space-y-1.5">
              {clients.map(c => (
                <div key={c.id} className="group/org relative">
                  <button onClick={() => setActiveClientId(c.id)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all truncate pr-16 ${activeClientId === c.id ? 'bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 shadow-lg shadow-indigo-500/5' : 'text-slate-400 hover:bg-slate-800 hover:text-slate-300'}`}>
                    <div className={`w-2 h-2 rounded-full shrink-0 ${activeClientId === c.id ? 'bg-indigo-400 animate-pulse' : 'bg-slate-700'}`}></div>
                    <span className="truncate">{c.name}</span>
                  </button>
                  <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1 opacity-0 group-hover/org:opacity-100 transition-opacity">
                    <button onClick={(e) => { e.stopPropagation(); setEditingOrg(c); setIsOrgModalOpen(true); }} className="p-1.5 hover:bg-slate-700 rounded-lg text-slate-500 hover:text-white transition-colors"><Edit2 className="w-3 h-3" /></button>
                    <button onClick={(e) => { e.stopPropagation(); handleDeleteOrg(c.id); }} className="p-1.5 hover:bg-rose-500/10 rounded-lg text-slate-500 hover:text-rose-400 transition-colors"><Trash2 className="w-3 h-3" /></button>
                  </div>
                </div>
              ))}
              <button onClick={() => { setEditingOrg(null); setIsOrgModalOpen(true); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-xs text-slate-600 font-bold border border-dashed border-slate-800 hover:border-slate-700 hover:text-slate-500 transition-all mt-2">
                <Plus className="w-4 h-4" /> Novo Cliente
              </button>
            </div>
          </div>
          <nav className="space-y-8"><div><label className="text-[10px] font-black text-slate-500 uppercase px-3 mb-4 block tracking-widest">Navegação</label><div className="space-y-1"><NavItem active={activePhase === 'dashboard'} onClick={() => setActivePhase('dashboard')} icon={<LayoutDashboard className="w-5 h-5" />} label="Visão Geral" /><NavItem active={activePhase === 'cases'} onClick={() => setActivePhase('cases')} icon={<Activity className="w-5 h-5" />} label="Gestão de Casos" color="rose" /></div></div><div><label className="text-[10px] font-black text-slate-500 uppercase px-3 mb-4 block tracking-widest">Ciclo de Inteligência</label><div className="space-y-1">{(Object.keys(PHASE_CONFIG) as CTIPhase[]).filter(p => p !== 'metrics').map(p => (<NavItem key={p} active={activePhase === p} onClick={() => setActivePhase(p)} icon={PHASE_CONFIG[p].icon} label={PHASE_CONFIG[p].title.split(' ')[0]} color={PHASE_CONFIG[p].color} />))}</div></div></nav>
        </div>
      </aside>
      <main className="flex-1 flex flex-col min-w-0 bg-slate-950 relative">
        <header className="h-20 border-b border-slate-800/50 px-10 flex items-center justify-between bg-slate-950/50 backdrop-blur-xl sticky top-0 z-10">
          <div className="flex items-center gap-6"><button onClick={toggleSidebar} className="p-2.5 bg-slate-900 border border-slate-800 hover:border-slate-700 rounded-xl text-slate-400 hover:text-white transition-all shadow-sm">{isSidebarOpen ? <ArrowLeft className="w-5 h-5" /> : <Menu className="w-5 h-5" />}</button><div className="flex items-center gap-2 text-sm font-medium"><span className="text-slate-500">CTI Program</span><ChevronRight className="w-4 h-4 text-slate-800" /><span className="text-slate-100 font-bold">{activeClient?.name}</span></div></div>
          <div className="flex items-center gap-4"><button disabled={loadingAi} className="flex items-center gap-2.5 bg-indigo-600 hover:bg-indigo-500 text-white px-5 py-2.5 rounded-xl text-xs font-black tracking-widest uppercase transition-all shadow-lg shadow-indigo-600/20 active:scale-95 disabled:opacity-50" onClick={handleAiInsight}>{loadingAi ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />} Analista IA</button></div>
        </header>
        <div className="flex-1 overflow-y-auto px-10 py-10">
          {aiInsight && (<div className="mb-10 p-6 bg-indigo-600/5 border border-indigo-500/20 rounded-2xl flex gap-5 animate-in slide-in-from-top-4 duration-500 relative group overflow-hidden"><div className="absolute top-0 left-0 w-1 h-full bg-indigo-500"></div><div className="bg-indigo-600/10 p-3 rounded-2xl h-fit"><Sparkles className="w-6 h-6 text-indigo-400" /></div><div className="flex-1"><h4 className="text-xs font-black text-indigo-400 uppercase tracking-widest mb-2">Insight de Inteligência Artificial</h4><p className="text-sm text-indigo-100 leading-relaxed font-medium whitespace-pre-wrap">{aiInsight}</p></div><button onClick={() => setAiInsight(null)} className="shrink-0 text-slate-700 hover:text-white transition-colors p-1"><X className="w-5 h-5" /></button></div>)}
          <div className="max-w-[1400px] mx-auto">{activePhase === 'dashboard' ? <Dashboard /> : activePhase === 'cases' ? <CasesManager /> : <PhaseView phase={activePhase as CTIPhase} />}</div>
        </div>
      </main>
    </div>
  );
}

export type CTIPhase = 'planning' | 'collection' | 'analysis' | 'dissemination' | 'feedback' | 'metrics';

export interface StatusHistory {
  status: string;
  date: string;
  action: 'Created' | 'Status Changed' | 'Edited';
}

export interface PIR {
  id: string;
  title: string;
  description: string;
  priority: 'High' | 'Medium' | 'Low';
  status: 'Active' | 'Draft' | 'Archived';
  history?: StatusHistory[];
}

export interface IntelligenceSource {
  id: string;
  pirId: string; // Relationship with PIR
  name: string;
  type: 'Internal' | 'OSINT' | 'FeedComercial' | 'FeedAberto' | 'DarkWeb';
  confidence: number; // 0-100 (OpenCTI standard)
  integrationDate: string;
  reliability: 'A' | 'B' | 'C' | 'D' | 'E' | 'F'; // Admiralty Scale
}

export interface MetricRecord {
  id: string;
  pirId: string;
  hasIncident: boolean;
  incidentDate?: string;
  discoveryDate: string;
  disseminationDate: string;
  wasPreviouslyReported: boolean;
  incidentPrevented: boolean;
  impactScale: 'Low' | 'Medium' | 'High' | 'Critical';
}

export interface DisseminationLog {
  id: string;
  date: string;
  type: 'Strategic' | 'Operational' | 'Tactical';
  reportName: string;
  observations?: string;
  attachmentName?: string;
  attachmentType?: string;
  attachmentData?: string; // Base64 simulated storage
}

export interface Report {
  id: string;
  pirId: string; // Relationship with PIR
  title: string;
  type: 'Strategic' | 'Operational' | 'Tactical';
  content: string;
  date: string;
}

export interface KPI {
  name: string;
  value: number;
  unit: string;
}

export interface ClientData {
  id: string;
  name: string;
  sector: string;
  description?: string;
  stakeholderName?: string;
  stakeholderEmail?: string;
  phases: {
    planning: { pirs: PIR[]; stakeholders: string[] };
    collection: { sources: IntelligenceSource[] };
    analysis: { reports: Report[]; ttps: string[] };
    dissemination: { 
      integrations: string[]; 
      alertsCount: number;
      logs: DisseminationLog[];
    };
    feedback: { kpis: KPI[]; improvements: string[] };
  };
  metrics: MetricRecord[];
}

export interface AppState {
  clients: ClientData[];
  activeClientId: string | null;
}

