  const DisseminationModal = () => {
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [form, setForm] = useState<Omit<DisseminationLog, 'id'>>(editingDissemination ? { ...editingDissemination } : {
      date: new Date().toISOString().split('T')[0],
      type: 'Tactical',
      reportName: '',
      observations: '',
      attachmentName: '',
      attachmentType: '',
      attachmentData: ''
    });

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const allowedExtensions = ['pdf', 'docx'];
      const extension = file.name.split('.').pop()?.toLowerCase();
      const allowedMimeTypes = [
          'application/pdf', 
          'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
      ];

      if (!extension || !allowedExtensions.includes(extension) || !allowedMimeTypes.includes(file.type)) {
        alert("Formato de arquivo inválido. Por favor, selecione um arquivo .PDF ou .DOCX.");
        if (fileInputRef.current) fileInputRef.current.value = "";
        return;
      }

      // Emular armazenamento local via Base64 para demonstração
      const reader = new FileReader();
      reader.onload = (event) => {
        setForm(prev => ({
          ...prev,
          attachmentName: file.name,
          attachmentType: file.type,
          attachmentData: event.target?.result as string
        }));
      };
      reader.readAsDataURL(file);
    };

    const removeAttachment = () => {
      setForm(prev => ({ ...prev, attachmentName: '', attachmentType: '', attachmentData: '' }));
      if (fileInputRef.current) fileInputRef.current.value = "";
    };

    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
        <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-sm" onClick={() => { setIsDisseminationModalOpen(false); setEditingDissemination(null); }} />
