      observations: '',
      attachmentName: '',
      attachmentType: '',
      attachmentData: ''
    });

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const allowedExtensions = ['pdf', 'docx'];
      const extension = file.name.split('.').pop()?.toLowerCase();
      const allowedMimeTypes = [
          'application/pdf', 
          'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
      ];

      if (!extension || !allowedExtensions.includes(extension) || !allowedMimeTypes.includes(file.type)) {
        alert("Formato de arquivo inválido. Por favor, selecione um arquivo .PDF ou .DOCX.");
        if (fileInputRef.current) fileInputRef.current.value = "";
        return;
      }

      const reader = new FileReader();
      reader.onload = (event) => {
        setForm(prev => ({
          ...prev,
          attachmentName: file.name,
          attachmentType: file.type,
          attachmentData: event.target?.result as string
        }));
      };
      reader.readAsDataURL(file);
    };

    const removeAttachment = () => {
      setForm(prev => ({ ...prev, attachmentName: '', attachmentType: '', attachmentData: '' }));
      if (fileInputRef.current) fileInputRef.current.value = "";
