        </div>

        {/* Chatbot Interface */}
        <div className={`fixed right-0 top-20 bottom-0 w-96 bg-slate-900 border-l border-slate-800 shadow-2xl z-30 transition-transform duration-500 flex flex-col ${isChatOpen ? 'translate-x-0' : 'translate-x-full'}`}>
