                 </div>
              </div>
              <button onClick={() => setIsChatOpen(false)} className="text-slate-500 hover:text-white transition-colors"><X className="w-5 h-5" /></button>
           </div>

           <div ref={chatScrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-950/50">
              {chatMessages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center px-6 opacity-30">
                   <Sparkles className="w-12 h-12 mb-4 text-indigo-500" />
