                </div>
              )}
              {chatMessages.map((msg, idx) => (
                <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                   <div className={`max-w-[85%] p-3 rounded-2xl text-sm leading-relaxed ${msg.role === 'user' ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-slate-800 text-slate-200 rounded-tl-none border border-slate-700'}`}>
                      {msg.content}
                   </div>
                </div>
              ))}
              {isAiTyping && (
                <div className="flex justify-start">
                   <div className="bg-slate-800 p-3 rounded-2xl rounded-tl-none border border-slate-700">
                      <div className="flex gap-1">
                         <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce"></div>
                         <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce delay-100"></div>
                         <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce delay-200"></div>
                      </div>
                   </div>
                </div>
              )}
           </div>

           <div className="p-4 border-t border-slate-800 bg-slate-900">
              <form onSubmit={(e) => { e.preventDefault(); handleSendMessage(); }} className="relative">
                 <input 
                    type="text" 
                    value={currentChatInput}
                    onChange={(e) => setCurrentChatInput(e.target.value)}
                    placeholder="Pergunte sobre correlações de dados..." 
                    className="w-full bg-slate-950 border border-slate-800 rounded-xl py-2.5 pl-4 pr-12 text-sm text-white focus:border-indigo-500 transition-colors"
                 />
                 <button type="submit" className="absolute right-2 top-1.5 p-1.5 bg-indigo-600 text-white rounded-lg hover:bg-indigo-500 transition-all">
                    <Send className="w-4 h-4" />
                 </button>
              </form>
           </div>
        </div>
      </main>
    </div>
  );
}

