                           </div>
                        </div>
                      </td>
                      <td className="py-5 px-6">
                        {m.incidentPrevented ? (
                          <div className="flex items-center gap-2 text-emerald-400 font-bold bg-emerald-400/5 border border-emerald-400/10 px-3 py-1.5 rounded-xl w-fit">
