      const now = new Date().toISOString();
      if (editingPir) {
        updatedPirs = updatedPirs.map(p => p.id === editingPir.id ? { ...pir, id: editingPir.id, history: [...(p.history || []), { status: pir.status, date: now, action: p.status !== pir.status ? 'Status Changed' : 'Edited' }] } : p);
