      <aside className={`bg-slate-900/60 border-r border-slate-800/50 transition-all duration-500 flex flex-col z-20 backdrop-blur-2xl ${isSidebarOpen ? 'w-80' : 'w-0 -translate-x-full overflow-hidden'}`}>
