        updatedPirs.push({ ...pir, id: Math.random().toString(36).substr(2, 9), history: [{ status: pir.status, date: now, action: 'Created' }] });
      }
      return { ...c, phases: { ...c.phases, planning: { ...c.phases.planning, pirs: updatedPirs } } };
