                              m.impactScale === 'Critical' ? 'bg-rose-500/20 text-rose-500 border-rose-500/20' :
                              m.impactScale === 'High' ? 'bg-orange-500/20 text-orange-500 border-orange-500/20' :
                              'bg-slate-700/50 text-slate-400 border-slate-600/50'
