  const [isThinking, setIsThinking] = useState(false);

  const activeClient = clients.find(c => c.id === activeClientId) || clients[0];

  const handleAddOrEditDissemination = (logData: Omit<DisseminationLog, 'id'>) => {
    const newLog: DisseminationLog = {
      ...logData,
      id: editingDissemination?.id || Math.random().toString(36).substr(2, 9),
    };

    setClients(prev => prev.map(client => {
      if (client.id !== activeClientId) return client;

      const existingLogs = client.phases.dissemination.logs;
      const updatedLogs = editingDissemination 
        ? existingLogs.map(l => l.id === editingDissemination.id ? newLog : l)
        : [...existingLogs, newLog];

      return {
        ...client,
        phases: {
          ...client.phases,
          dissemination: {
            ...client.phases.dissemination,
            logs: updatedLogs
          }
        }
      };
    }));

    setIsDisseminationModalOpen(false);
    setEditingDissemination(null);
  };

