             <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
             <span className="text-xs font-bold text-slate-400">{activeClient.name}</span>
          </div>
          <div className="w-px h-6 bg-slate-800" />
          <button className="p-2 hover:bg-slate-900 rounded-full transition-colors text-slate-400 hover:text-white">
            <Bell className="w-5 h-5" />
          </button>
        </div>
      </header>

      {/* Main Content */}
      <div className="pt-24 px-6 pb-12 max-w-7xl mx-auto grid grid-cols-12 gap-8">

        {/* Navigation Sidebar */}
        <div className="col-span-3 space-y-8">
           <div className="bg-slate-900/50 border border-slate-800 rounded-3xl p-4 space-y-1">
              {(Object.entries(PHASE_CONFIG) as [CTIPhase, typeof PHASE_CONFIG[CTIPhase]][]).map(([key, config]) => (
                <button 
                  key={key}
                  onClick={() => setActivePhase(key)}
                  className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl transition-all duration-300 group ${activePhase === key ? 'bg-slate-800 text-white shadow-lg' : 'hover:bg-slate-900 text-slate-400'}`}
                >
                  <div className={`w-8 h-8 rounded-xl flex items-center justify-center transition-colors ${activePhase === key ? getPhaseColorClass(config.color, false) : 'bg-slate-950 text-slate-600 group-hover:text-slate-400'}`}>
                    {config.icon}
                  </div>
                  <div className="text-left">
                    <p className={`text-xs font-black uppercase tracking-wider ${activePhase === key ? getPhaseColorClass(config.color, true) : 'text-slate-600'}`}>{key}</p>
                    <p className="text-sm font-bold">{config.title}</p>
                  </div>
                </button>
              ))}
           </div>

           {/* AI Assistant Widget */}
           <div className="bg-gradient-to-br from-indigo-950 to-slate-900 border border-indigo-900/50 rounded-3xl p-6 relative overflow-hidden">
              <div className="absolute top-0 right-0 p-4 opacity-10">
                <BrainCircuit className="w-24 h-24 text-indigo-400" />
              </div>
              <h3 className="font-bold text-white mb-2 flex items-center gap-2"><BrainCircuit className="w-4 h-4 text-indigo-400" /> Sentinel AI</h3>
              <p className="text-xs text-indigo-200/60 mb-4 leading-relaxed">Analise seus dados de inteligência para encontrar correlações ocultas.</p>
              <textarea 
                value={aiPrompt}
                onChange={e => setAiPrompt(e.target.value)}
                className="w-full bg-slate-950/50 border border-indigo-900/50 rounded-xl p-3 text-xs text-indigo-100 placeholder-indigo-900/50 resize-none mb-3 focus:outline-none focus:border-indigo-500 transition-colors"
                placeholder="Ex: Identifique padrões nos logs de disseminação..."
                rows={3}
              />
              <button 
                onClick={handleGenerateInsight}
                disabled={isThinking || !aiPrompt}
                className="w-full py-2 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed text-white text-xs font-bold rounded-xl transition-all shadow-lg shadow-indigo-900/20"
              >
                {isThinking ? 'Analisando...' : 'Gerar Insight'}
              </button>

              {aiResponse && (
                <div className="mt-4 p-3 bg-slate-950/50 rounded-xl border border-indigo-900/30 max-h-40 overflow-y-auto custom-scrollbar">
                   <p className="text-xs text-indigo-100 leading-relaxed whitespace-pre-wrap">{aiResponse}</p>
                </div>
              )}
           </div>
        </div>

        {/* Phase Content Area */}
        <div className="col-span-9 space-y-6">
           {/* Header of Phase */}
           <div className="flex items-end justify-between">
              <div>
                <h2 className="text-3xl font-black text-white mb-2">{PHASE_CONFIG[activePhase].title}</h2>
                <p className="text-slate-400 text-sm max-w-xl">Gerencie o ciclo de vida da inteligência, desde o planejamento até a entrega de valor.</p>
              </div>
              {activePhase === 'dissemination' && (
                <button 
                  onClick={() => { setEditingDissemination(null); setIsDisseminationModalOpen(true); }}
                  className="flex items-center gap-2 bg-white text-slate-950 hover:bg-slate-200 px-5 py-2.5 rounded-xl text-sm font-bold transition-all shadow-lg shadow-white/5"
                >
                  <Plus className="w-4 h-4" /> Novo Registro
                </button>
              )}
           </div>

           {/* Dynamic Content based on Phase */}
           <div className="bg-slate-900/50 border border-slate-800 rounded-[2.5rem] p-8 min-h-[500px]">
              {activePhase === 'dissemination' ? (
                <div className="space-y-4">
                  {activeClient.phases.dissemination.logs.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-64 text-slate-500">
                      <Share2 className="w-12 h-12 mb-4 opacity-20" />
                      <p>Nenhum registro de disseminação encontrado.</p>
                    </div>
                  ) : (
                    <div className="grid gap-3">
                      {activeClient.phases.dissemination.logs.map(log => (
                        <div key={log.id} className="group flex items-center justify-between p-4 bg-slate-950 border border-slate-800 hover:border-slate-700 rounded-2xl transition-all">
                          <div className="flex items-center gap-4">
                            <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                              log.type === 'Strategic' ? 'bg-blue-500/10 text-blue-500' :
                              log.type === 'Operational' ? 'bg-emerald-500/10 text-emerald-500' :
                              'bg-purple-500/10 text-purple-500'
                            }`}>
                              <Share2 className="w-5 h-5" />
                            </div>
                            <div>
                              <h4 className="font-bold text-white text-sm">{log.reportName || 'Sem nome'}</h4>
                              <div className="flex items-center gap-2 text-xs text-slate-500">
                                <span>{new Date(log.date).toLocaleDateString()}</span>
                                <span>•</span>
                                <span>{log.type}</span>
                                <span>•</span>
                                <span className={log.status === 'Disseminated' ? 'text-emerald-400' : 'text-amber-400'}>{log.status}</span>
                              </div>
                            </div>
                          </div>
                          <button 
                            onClick={() => { setEditingDissemination(log); setIsDisseminationModalOpen(true); }}
                            className="opacity-0 group-hover:opacity-100 p-2 hover:bg-slate-900 rounded-lg text-slate-400 transition-all"
                          >
                            <ChevronRight className="w-4 h-4" />
                          </button>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-600">
                  <Layout className="w-16 h-16 mb-4 opacity-20" />
                  <p className="font-medium">Módulo {PHASE_CONFIG[activePhase].title} em desenvolvimento.</p>
                  <p className="text-sm opacity-60">Utilize a aba Disseminação para ver a funcionalidade completa.</p>
                </div>
              )}
           </div>
        </div>
      </div>

      {isDisseminationModalOpen && <DisseminationModal />}
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { 
  Target, Search, BarChart3, Share2, X, AlertCircle, 
  Plus, ChevronRight, BrainCircuit, Shield, 
  LayoutDashboard, Bell, Activity, Clock, Zap, CheckCircle
} from 'lucide-react';
import { 
  AppState, ClientData, DisseminationLog, CTIPhase 
} from './types';
import { PHASE_CONFIG } from './constants';
import { generateCTIInsight } from './services/gemini';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  BarChart, Bar, Cell
} from 'recharts';

// Mock Data
