       { id: 'm2', pirId: 'pir-1', hasIncident: false, discoveryDate: '2024-04-10T09:00:00', disseminationDate: '2024-04-10T10:30:00', wasPreviouslyReported: true, incidentPrevented: true, impactScale: 'Low' },
       { id: 'm3', pirId: 'pir-2', hasIncident: true, discoveryDate: '2024-04-15T16:00:00', disseminationDate: '2024-04-16T09:00:00', wasPreviouslyReported: false, incidentPrevented: false, impactScale: 'High' }
    ]
  }
];

type ViewState = CTIPhase | 'dashboard';

export default function App() {
  const [clients, setClients] = useState<ClientData[]>(INITIAL_CLIENTS);
  const [activeClientId, setActiveClientId] = useState<string>('1');
  const [activeView, setActiveView] = useState<ViewState>('dashboard');

  // Dissemination Modal State
  const [isDisseminationModalOpen, setIsDisseminationModalOpen] = useState(false);
  const [editingDissemination, setEditingDissemination] = useState<DisseminationLog | null>(null);
  const [disseminationModalPirId, setDisseminationModalPirId] = useState<string | null>(null);

  // AI Insight State (Chat only)
  const [aiPrompt, setAiPrompt] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isThinking, setIsThinking] = useState(false);

  const activeClient = clients.find(c => c.id === activeClientId) || clients[0];

  // Helper to calculate stats
  const stats = useMemo(() => {
    return {
      pirs: activeClient.phases.planning.pirs.filter(p => p.status === 'Active').length,
      sources: activeClient.phases.collection.sources.length,
      reports: activeClient.phases.analysis.reports.length,
      alerts: activeClient.phases.dissemination.logs.filter(l => l.status === 'Disseminated' || l.status === 'Acknowledged').length,
      totalAlerts: activeClient.phases.dissemination.logs.length
    };
  }, [activeClient]);

  const chartData = useMemo(() => {
    return activeClient.phases.dissemination.logs.reduce((acc: any[], log) => {
       const date = log.date.substring(5); // MM-DD
       const existing = acc.find(a => a.name === date);
       if (existing) existing.value++;
       else acc.push({ name: date, value: 1 });
       return acc;
    }, []).sort((a: any, b: any) => a.name.localeCompare(b.name));
  }, [activeClient]);

  const handleAddOrEditDissemination = (logData: Omit<DisseminationLog, 'id'>) => {
    const newLog: DisseminationLog = {
      ...logData,
      id: editingDissemination?.id || Math.random().toString(36).substr(2, 9),
    };

    setClients(prev => prev.map(client => {
      if (client.id !== activeClientId) return client;

      const existingLogs = client.phases.dissemination.logs;
      const updatedLogs = editingDissemination 
        ? existingLogs.map(l => l.id === editingDissemination.id ? newLog : l)
        : [...existingLogs, newLog];

      return {
        ...client,
        phases: {
          ...client.phases,
          dissemination: {
            ...client.phases.dissemination,
            logs: updatedLogs
          }
        }
      };
    }));

    setIsDisseminationModalOpen(false);
    setEditingDissemination(null);
  };

  const handleGenerateInsight = async () => {
    if (!aiPrompt) return;
    setIsThinking(true);
    const context = JSON.stringify(activeClient, null, 2);
    const response = await generateCTIInsight(aiPrompt, context);
    setAiResponse(response || 'Sem resposta.');
    setIsThinking(false);
  };

  const DisseminationModal = () => {
    const [form, setForm] = useState<Omit<DisseminationLog, 'id'>>(
      editingDissemination 
        ? { ...editingDissemination } 
        : { 
            pirId: disseminationModalPirId || activeClient?.phases.planning.pirs[0]?.id || '', 
            date: new Date().toISOString().split('T')[0], 
            type: 'Tactical', 
            status: 'Pending', 
            reportName: '', 
            deliveryChannel: '', 
            notifiedTeam: '', 
            observations: '' 
          }
    );
    const [error, setError] = useState('');

    const validateEmail = (email: string) => {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    };

    const handleSave = () => {
        if (!form.pirId) {
            setError('Por favor, selecione um PIR para vincular este log.');
            return;
        }
        if (form.deliveryChannel && !validateEmail(form.deliveryChannel)) {
            setError('Por favor, insira um e-mail válido no Canal de Envio.');
            return;
        }
        setError('');
        handleAddOrEditDissemination(form);
    };

    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
        <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-md" onClick={() => { setIsDisseminationModalOpen(false); setEditingDissemination(null); }} />
        <div className="relative bg-slate-900 border border-slate-800 w-full max-w-xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95">
          <div className="px-8 py-6 border-b border-slate-800 flex justify-between items-center bg-slate-800/20">
            <h3 className="font-bold text-xl flex items-center gap-3"><Share2 className="w-6 h-6 text-purple-500" /> {editingDissemination ? 'Editar Log' : 'Nova Disseminação/Alerta'}</h3>
            <button onClick={() => { setIsDisseminationModalOpen(false); setEditingDissemination(null); }}><X className="w-6 h-6 text-slate-500 hover:text-white transition-colors" /></button>
          </div>
          <div className="p-8 space-y-6 max-h-[70vh] overflow-y-auto custom-scrollbar">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Vincular a PIR</label>
              <select value={form.pirId} onChange={e => setForm({...form, pirId: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-2xl py-3 px-4 text-sm text-white outline-none focus:border-purple-500 transition-colors">
                <option value="" className="bg-slate-950 text-slate-300">Selecione um PIR...</option>
                {activeClient?.phases.planning.pirs.map(p => <option key={p.id} value={p.id} className="bg-slate-950 text-slate-300">{p.title}</option>)}
              </select>
            </div>
            <div className="grid grid-cols-2 gap-5">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Data</label>
                <input type="date" value={form.date} onChange={e => setForm({...form, date: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-2xl py-3 px-4 text-sm text-white outline-none focus:border-purple-500 transition-colors" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Nível</label>
                <select value={form.type} onChange={e => setForm({...form, type: e.target.value as any})} className="w-full bg-slate-950 border border-slate-800 rounded-2xl py-3 px-4 text-sm text-white outline-none focus:border-purple-500 transition-colors">
                  <option value="Tactical" className="bg-slate-950 text-slate-300">Tático</option>
                  <option value="Operational" className="bg-slate-950 text-slate-300">Operacional</option>
                  <option value="Strategic" className="bg-slate-950 text-slate-300">Estratégico</option>
                </select>
              </div>
            </div>
            <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Status Atual</label>
                <select value={form.status} onChange={e => setForm({...form, status: e.target.value as any})} className="w-full bg-slate-950 border border-slate-800 rounded-2xl py-3 px-4 text-sm text-white outline-none focus:border-purple-500 transition-colors">
                   <option value="Pending" className="bg-slate-950 text-slate-300">Pendente / Não Enviado</option>
                   <option value="Disseminated" className="bg-slate-950 text-slate-300">Disseminado / Enviado</option>
                   <option value="Acknowledged" className="bg-slate-950 text-slate-300">Reconhecido (Ack)</option>
                </select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Nome do Relatório (Fonte de Dados)</label>
              <input type="text" value={form.reportName} onChange={e => setForm({...form, reportName: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-2xl py-3 px-4 text-sm text-white outline-none focus:border-purple-500 transition-colors" placeholder="Ex: IOC_Feed_May.csv" />
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Canal de Envio (Email)</label>
                <input type="email" value={form.deliveryChannel} onChange={e => { setForm({...form, deliveryChannel: e.target.value}); setError(''); }} className={`w-full bg-slate-950 border ${error.includes('e-mail') ? 'border-rose-500' : 'border-slate-800'} rounded-2xl py-3 px-4 text-sm text-white outline-none focus:border-purple-500 transition-colors`} placeholder="ex: soc@empresa.com" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Time Notificado</label>
                <input type="text" value={form.notifiedTeam} onChange={e => setForm({...form, notifiedTeam: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-2xl py-3 px-4 text-sm text-white outline-none focus:border-purple-500 transition-colors" placeholder="ex: SOC N2, Incident Response" />
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Demais Observações</label>
              <textarea rows={3} value={form.observations} onChange={e => setForm({...form, observations: e.target.value})} className="w-full bg-slate-950 border border-slate-800 rounded-2xl py-3 px-4 text-sm text-white outline-none focus:border-purple-500 resize-none transition-colors" placeholder="Contexto adicional da disseminação..." />
            </div>
            {error && <p className="text-xs text-rose-500 font-bold flex items-center gap-2"><AlertCircle className="w-4 h-4" /> {error}</p>}
          </div>
          <div className="px-8 py-6 bg-slate-800/20 border-t border-slate-800 flex justify-end gap-4">
            <button onClick={() => { setIsDisseminationModalOpen(false); setEditingDissemination(null); }} className="text-sm text-slate-400 font-bold hover:text-white transition-colors">Cancelar</button>
            <button onClick={handleSave} className="bg-purple-600 hover:bg-purple-500 text-white px-8 py-3 rounded-2xl text-sm font-black shadow-lg shadow-purple-900/20 transition-all hover:scale-105 active:scale-95">Salvar Log</button>
          </div>
        </div>
      </div>
    );
  };

  const getPhaseColorClass = (color: string, isText: boolean) => {
    switch (color) {
      case 'blue': return isText ? 'text-blue-500' : 'bg-blue-500/20 text-blue-500';
      case 'emerald': return isText ? 'text-emerald-500' : 'bg-emerald-500/20 text-emerald-500';
      case 'amber': return isText ? 'text-amber-500' : 'bg-amber-500/20 text-amber-500';
      case 'purple': return isText ? 'text-purple-500' : 'bg-purple-500/20 text-purple-500';
      default: return isText ? 'text-slate-500' : 'bg-slate-500/20 text-slate-500';
    }
  };

  const Dashboard = () => (
    <div className="space-y-8 animate-in fade-in slide-in-from-right-4 duration-500">
        <div className="flex justify-between items-end">
           <div>
              <h1 className="text-4xl font-black text-white tracking-tight mb-2">Visão Geral</h1>
              <p className="text-slate-400 font-medium">Monitoramento em tempo real do programa de inteligência.</p>
           </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
           {[
             { label: 'PIRs Ativos', value: stats.pirs, color: 'blue', icon: Target },
             { label: 'Fontes Monitoradas', value: stats.sources, color: 'emerald', icon: Search },
             { label: 'Relatórios Produzidos', value: stats.reports, color: 'amber', icon: BarChart3 },
             { label: 'Alertas Disseminados', value: stats.alerts, color: 'purple', icon: Share2 }
           ].map((s, i) => (
             <div key={i} className="bg-slate-900/50 border border-slate-800 p-6 rounded-[2rem] hover:border-slate-700 transition-all group relative overflow-hidden">
                <div className={`absolute top-0 right-0 w-32 h-32 bg-${s.color}-500/10 rounded-full -mr-10 -mt-10 blur-3xl transition-all group-hover:bg-${s.color}-500/20`}></div>
                <div className="flex justify-between items-start mb-4 relative z-10">
                   <div className={`p-3 bg-${s.color}-500/10 text-${s.color}-400 rounded-2xl`}>
                      <s.icon className="w-6 h-6" />
                   </div>
                </div>
                <div className="relative z-10">
                   <h3 className="text-4xl font-bold text-white mb-1 group-hover:scale-105 transition-transform origin-left">{s.value}</h3>
                   <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{s.label}</p>
                </div>
             </div>
           ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
           <div className="lg:col-span-2 bg-slate-900/50 border border-slate-800 p-8 rounded-[2.5rem] shadow-xl">
              <h3 className="text-sm font-black text-slate-300 uppercase tracking-widest mb-8 flex items-center gap-2">
                 <Activity className="w-4 h-4 text-indigo-500" /> Volume de Alertas & Disseminações
              </h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={chartData}>
                    <defs>
                      <linearGradient id="colorAlerts" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
